package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;
@Data
@AllArgsConstructor
@NoArgsConstructor
public class DocumentExtractionResult {
    private Map<Integer, Page> pages;
    private Integer noOfPages;
    private AccountSummary accountSummary;
    private boolean isStatementWithReversedOrder;
    // this field indicate statement is in ascending order but transactions in particular date is in reverse
    private boolean isStatementWithReverseOrderPerDate;
    private PreProcessVerificationResult preProcessVerificationResult;
    private Integer transactionDateIndexByHeader;
    private Integer valueDateIndexByHeader;
    private Boolean bankSpecificProcessing = Boolean.FALSE;
    private BankSpecificStatementMetadata bankSpecificStatementMetadata;
    private boolean isStatementWithoutBalance;
    private boolean skipFurtherProcessing = false;

    public DocumentExtractionResult copy() {
        Map<Integer, Page> copyPages = this.pages.entrySet().stream()
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        entry -> entry.getValue().copy()
                ));


        return new DocumentExtractionResult(
            copyPages,
            this.noOfPages,
            this.accountSummary != null ? this.accountSummary.copy() : null,
            this.isStatementWithReversedOrder,
            this.isStatementWithReverseOrderPerDate,
            this.preProcessVerificationResult != null ? this.preProcessVerificationResult.copy() : null,
                this.transactionDateIndexByHeader,
                this.valueDateIndexByHeader,
                this.bankSpecificProcessing,
                this.bankSpecificStatementMetadata != null ? this.bankSpecificStatementMetadata.copy() : null,
                this.isStatementWithoutBalance,
                this.skipFurtherProcessing
        );  
    }

    public DocumentExtractionResult copy(Integer numberOfPages) {
        Map<Integer, Page> filteredPages = this.pages.entrySet().stream()
                .filter(entry -> entry.getKey() <= numberOfPages)
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                    entry -> entry.getValue().copy()
                ));

        return new DocumentExtractionResult(
            filteredPages,
            Math.min(numberOfPages, filteredPages.size()),
            this.accountSummary != null ? this.accountSummary.copy() : null,
            this.isStatementWithReversedOrder,
            this.isStatementWithReverseOrderPerDate,
            this.preProcessVerificationResult != null ? this.preProcessVerificationResult.copy() : null,
                this.transactionDateIndexByHeader,
                this.valueDateIndexByHeader,
                this.bankSpecificProcessing,
                this.bankSpecificStatementMetadata != null ? this.bankSpecificStatementMetadata.copy() : null,
                this.isStatementWithoutBalance,
                this.skipFurtherProcessing
        );
    }

    public DocumentExtractionResult copyOfPage(Integer pageNumber) {

        Map<Integer, Page> filteredPages = this.pages.entrySet().stream()
                .filter(entry -> Objects.equals(entry.getKey(), pageNumber))
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        entry -> entry.getValue().copy()
                ));

        return new DocumentExtractionResult(
                filteredPages,
                Math.min(1, filteredPages.size()),
                this.accountSummary != null ? this.accountSummary.copy() : null,
                this.isStatementWithReversedOrder,
                this.isStatementWithReverseOrderPerDate,
                this.preProcessVerificationResult != null ? this.preProcessVerificationResult.copy() : null,
                this.transactionDateIndexByHeader,
                this.valueDateIndexByHeader,
                this.bankSpecificProcessing,
                this.bankSpecificStatementMetadata != null ? this.bankSpecificStatementMetadata.copy() : null,
                this.isStatementWithoutBalance,
                this.skipFurtherProcessing
        );
    }

}
