package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

@Data
@AllArgsConstructor
@NoArgsConstructor
public class Table {
    private Float x1;
    private Float y1;
    private Float x2;
    private Float y2;
    private Float x3;
    private Float y3;
    private Float x4;
    private Float y4;
    private Integer pageNumber;
    private List<ColumnDataType> colType;
    private List<ColumnTransactionType> txnColType;
    private Map<Integer, Map<Integer, TableCell>> cells;
    private boolean isBankTransactions;
    private Integer totalRows;
    private Integer totalColumns;
    private Integer spanOffset;
    private Integer spanLength;
    private List<Float> columnBoundaries;

    public boolean getIsTransactionTable() {
        return isBankTransactions;
    }

    /**
     * Gets the content of a specific row as a space-separated string
     * @param rowIndex the index of the row to retrieve
     * @return String containing the contents of all cells in the row, or empty string if row doesn't exist
     */
    public String getRowContent(Integer rowIndex) {
        if (cells == null || !cells.containsKey(rowIndex)) {
            return "";
        }

        Map<Integer, TableCell> rowCells = cells.get(rowIndex);
        if (rowCells == null || rowCells.isEmpty()) {
            return "";
        }

        return rowCells.values().stream()
                .sorted(Comparator.comparing(TableCell::getColindex))
                .map(TableCell::getContent)
                .filter(content -> content != null && !content.isEmpty())
                .collect(Collectors.joining(" "));

    }

    public Table copy() {


        return new Table(
            this.x1,
            this.y1,    
            this.x2,
            this.y2,
            this.x3,
            this.y3,
            this.x4,
            this.y4,    
            this.pageNumber,
            this.colType,
            this.txnColType,
            this.cells.entrySet().stream()
                .collect(Collectors.toMap(
                    Map.Entry::getKey,
                    entry -> entry.getValue().entrySet().stream()
                        .collect(Collectors.toMap(
                            Map.Entry::getKey,
                            cellEntry -> cellEntry.getValue().copy()
                        ))
                ))
            ,
            this.isBankTransactions,
            this.totalRows,
            this.totalColumns,
            this.spanOffset,
            this.spanLength,
            this.columnBoundaries
        );
    }

}

