package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

@Data
@AllArgsConstructor
@NoArgsConstructor
public class TableCell {
    private Float x1;
    private Float y1;
    private Float x2;
    private Float y2;
    private Float x3;
    private Float y3;
    private Float x4;
    private Float y4;
    private Integer colspan;
    private Integer rowspan;
    private Integer rowindex;
    private Integer colindex;
    private List<Word> words;
    private boolean isHeaderOrFooterCell=false;

    public String getContent() {
        if (words == null || words.isEmpty()) {
            return "";
        }

        // Sort words first by pageIndex then by wordIndex (lower values first)
        List<Word> sortedWords = new ArrayList<>(words);
        Collections.sort(sortedWords, new Comparator<Word>() {
            @Override
            public int compare(Word w1, Word w2) {
                // First compare by pageIndex (lower page first)
                int pageCompare = Integer.compare(w1.getPageIndex(), w2.getPageIndex());
                if (pageCompare != 0) {
                    return pageCompare;
                }

                // If same page, compare by wordIndex (lower word first)
                return Integer.compare(w1.getWordIndex(), w2.getWordIndex());
            }
        });

        // Sort words by x1 coordinate (left to right)
        Collections.sort(sortedWords, Comparator.comparing(Word::getActualX1));

        // Sort words by y1 coordinate (top to bottom)
        Collections.sort(sortedWords, Comparator.comparing(Word::getActualY1));

        return sortedWords.stream()
                .map(Word::getContent)
                .collect(Collectors.joining(" "))
                .trim();
        //return words.stream().map(Word::getContent).collect(Collectors.joining(" "));
    }

    public TableCell copy() {
        return new TableCell(
            this.x1,
            this.y1,
            this.x2,  
            this.y2,
            this.x3,
            this.y3,
            this.x4,
            this.y4,
            this.colspan,
            this.rowspan,
            this.rowindex,
            this.colindex,
            this.words.stream().map(Word::copy).collect(Collectors.toList()),
            this.isHeaderOrFooterCell
        );
    }

}
