package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@AllArgsConstructor
@NoArgsConstructor
public class Word {
    private Float x1;
    private Float y1;
    private Float x2;
    private Float y2;
    private Float x3;
    private Float y3;
    private Float x4;
    private Float y4;
    private String content;
    private Integer pageNumber;
    private Float width;
    private Float height;
    private int pageIndex;
    private int wordIndex;
    private EPdfWord ePdfWord; // New field for character-level information

    // Constructor without EPdfWord for backward compatibility
    public Word(String content, float x1, float y1, float x2, float y2, float x3, float y3, float x4, float y4,
                int pageNumber, float width, float height, int pageIndex, int wordIndex) {
        this.content = content;
        this.x1 = x1;
        this.y1 = y1;
        this.x2 = x2;
        this.y2 = y2;
        this.x3 = x3;
        this.y3 = y3;
        this.x4 = x4;
        this.y4 = y4;
        this.pageNumber = pageNumber;
        this.width = width;
        this.height = height;
        this.pageIndex = pageIndex;
        this.wordIndex = wordIndex;
    }

    public Word copy() {
        Word copy = new Word(
                this.content,
                this.x1,
                this.y1,
                this.x2,
                this.y2,
                this.x3,
                this.y3,
                this.x4,
                this.y4,
                this.pageNumber,
                this.width,
                this.height,
                this.pageIndex,
                this.wordIndex
        );

        // Copy EPdfWord if present
        if (this.ePdfWord != null) {
            copy.setEPdfWord(this.ePdfWord.copy());
        }

        return copy;
    }

    public String getContent() {
        if(null != ePdfWord && ePdfWord.getContent() != null && !ePdfWord.getContent().isEmpty()) {
            return ePdfWord.getContent().trim();
        }
        if(null != content && !content.isEmpty()) {
            return content.trim();
        }
        return content;
    }

    public Float getActualX1(){
        if(null != ePdfWord && ePdfWord.getX1() != 0.0f) return ePdfWord.getX1();

        return x1;
    }

    public Float getActualY1(){
        if(null != ePdfWord &&  ePdfWord.getY1() != 0.0f) return ePdfWord.getY1();

        return y1;
    }
}
