package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.List;

@Data
@AllArgsConstructor
@NoArgsConstructor(force = true)
public class ColumnRange {
    private Float x1;
    private Float y1;
    private Float x2;
    private Float y2;
    private Float x3;
    private Float y3;
    private Float x4;
    private Float y4;

    public ColumnRange copy() {
        return new ColumnRange(
            this.x1,
            this.y1,
            this.x2,
            this.y2,
            this.x3,
            this.y3,
            this.x4,
            this.y4
        );
    }

    public Float getMinX1() {
        if (x1 == null && x4 == null) {
            return null;
        }
        if (x1 == null) {
            return x4;
        }
        if (x4 == null) {
            return x1;
        }
        return Math.min(x1, x4);
    }

    public Float getMaxX2() {
        if (x2 == null && x3 == null) {
            return null;
        }
        if (x2 == null) {
            return x3;
        }
        if (x3 == null) {
            return x2;
        }
        return Math.max(x2, x3);
    }

    public static Float getSeparationPoint(ColumnRange first, ColumnRange second) {
        if (first == null || second == null) {
            return null;
        }

        Float firstEnd = first.getMaxX2();
        Float secondStart = second.getMinX1();

        if (firstEnd == null || secondStart == null) {
            return null;
        }

        // If columns overlap, return midpoint of overlap
        if (firstEnd > secondStart) {
            return (firstEnd + secondStart) / 2;
        }

        // If columns have gap, return midpoint of gap
        return (firstEnd + secondStart) / 2;
    }

    public static List<Float> getColumnCoordinates(List<ColumnRange> columnRanges) {
        if (columnRanges == null || columnRanges.isEmpty()) {
            return new ArrayList<>();
        }
        // Sort column ranges by minX1 coordinate
        columnRanges.sort((c1, c2) -> {
            Float x1 = c1.getMinX1();
            Float x2 = c2.getMinX1();
            if (x1 == null && x2 == null) return 0;
            if (x1 == null) return 1;
            if (x2 == null) return -1;
            return x1.compareTo(x2);
        });

        List<Float> coordinates = new ArrayList<>();

        // Add first column's start coordinate
        ColumnRange firstColumn = columnRanges.get(0);
        Float firstStart = firstColumn.getMinX1();
        if (firstStart != null) {
            coordinates.add(firstStart);
        }

        // Add separation points between columns
        for (int i = 0; i < columnRanges.size() - 1; i++) {
            Float separationPoint = getSeparationPoint(columnRanges.get(i), columnRanges.get(i + 1));
            if (separationPoint != null) {
                coordinates.add(separationPoint);
            }
        }

        // Add last column's end coordinate
        ColumnRange lastColumn = columnRanges.get(columnRanges.size() - 1);
        Float lastEnd = lastColumn.getMaxX2();
        if (lastEnd != null) {
            coordinates.add(lastEnd);
        }

        return coordinates;
    }



}
