package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.Data;

@Data
public class CellRange {
    private Float x1;
    private Float x2;
    private Float width;

    public CellRange(Float x1, Float x2) {
        this.x1 = x1;
        this.x2 = x2;
        this.width = x2 - x1;
    }

    public void updateRange(Float newX1, Float newX2) {
        this.x1 = Math.min(this.x1, newX1);
        this.x2 = Math.max(this.x2, newX2);
        this.width = this.x2 - this.x1;
    }
