import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.*;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;
import java.awt.geom.Point2D;
import java.io.*;
import java.util.*;

public class Probe {
    static class LineFinder extends PDFGraphicsStreamEngine {
        int hLines=0, vLines=0, rects=0, fills=0;
        List<float[]> path = new ArrayList<>();
        LineFinder(PDPage page){ super(page); }
        public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) { rects++; }
        public void drawImage(PDImage pdImage) {}
        public void clip(int windingRule) {}
        public void moveTo(float x, float y) { path.add(new float[]{x,y}); }
        public void lineTo(float x, float y) { 
            if(!path.isEmpty()){
                float[] prev = path.get(path.size()-1);
                if(Math.abs(prev[1]-y)<0.5 && Math.abs(prev[0]-x)>3) hLines++;
                if(Math.abs(prev[0]-x)<0.5 && Math.abs(prev[1]-y)>3) vLines++;
            }
            path.add(new float[]{x,y});
        }
        public Point2D getCurrentPoint() { return path.isEmpty()? new Point2D.Float(0,0) : new Point2D.Float(path.get(path.size()-1)[0], path.get(path.size()-1)[1]); }
        public void curveTo(float x1,float y1,float x2,float y2,float x3,float y3){ path.add(new float[]{x3,y3}); }
        public void closePath() {}
        public void endPath() { path.clear(); }
        public void strokePath() { path.clear(); }
        public void fillPath(int windingRule) { fills++; path.clear(); }
        public void fillAndStrokePath(int windingRule) { fills++; path.clear(); }
        public void shadingFill(COSName shadingName) {}
    }
    public static void main(String[] a) throws Exception {
        File root = new File(a[0]);
        File[] banks = root.listFiles();
        Arrays.sort(banks);
        for(File b : banks){
            if(!b.isDirectory()) continue;
            File[] fs = b.listFiles();
            Arrays.sort(fs);
            for(File f : fs){
                if(!f.getName().endsWith(".pdf")) continue;
                try(PDDocument doc = Loader.loadPDF(f)){
                    PDPage page = doc.getPage(Math.min(0, doc.getNumberOfPages()-1));
                    // use page 1
                    LineFinder lf = new LineFinder(page);
                    lf.processPage(page);
                    System.out.printf("%-32s %-12s pages=%-3d h=%-4d v=%-4d rect=%-4d fill=%-4d%n", b.getName(), f.getName(), doc.getNumberOfPages(), lf.hLines, lf.vLines, lf.rects, lf.fills);
                } catch(Exception e){
                    System.out.printf("%-32s %-12s ERROR %s%n", b.getName(), f.getName(), e.getMessage());
                }
            }
        }
    }
}
