@Service
public class StatementBasicDetailExtractor {

    private static final Logger logger = LoggerFactory.getLogger(StatementBasicDetailExtractor.class);

    private AzureOpenAiCommunicationService azureOpenAiCommunicationService;

    private static final ObjectMapper objectMapper = new ObjectMapper();

    @Autowired
    public void setAzureOpenAiCommunicationService(AzureOpenAiCommunicationService azureOpenAiCommunicationService) {
        this.azureOpenAiCommunicationService = azureOpenAiCommunicationService;
    }

    // Expected output
    String expectedOutput = "{ \"account_number\": \"\", \"customer_name\": \"\", \"customer_address\": \"\", \"customer_email\": \"\", \"customer_mobile_number\": \"\", \"customer_PAN_number\": \"\",  \"customer_AADHAAR_number\": \"\",  \"IFSC_code_of_bank\": \"\",  \"IMCR_code_of_bank\": \"\", \"statement_from_date\": \"dd/MM/yyyy\", \"statement_to_date\": \"dd/MM/yyyy\", \"Sanction_Amount/Account_Limit\" : \"\"}";

    public AccountSummary getBasicDetails(DocumentExtractionResult document) {

        String response = getBasicDetailsFromAI(document);
        return postProcessResponse(response);

    }

    public String getBasicDetailsFromAI(DocumentExtractionResult document){
        String text =  extractNonTableContentFromDocument(document, 1);
        String prompt = generatePrompt(text,expectedOutput);
        return azureOpenAiCommunicationService.generateResponse(prompt);
    }

    // Utility method to process multiple pages
    public String extractNonTableContentFromDocument(DocumentExtractionResult document, int pageNumber) {
        return extractNonTableContent(document.getPages().get(pageNumber));
    }

    public String extractNonTableContent(Page page) {
        if (page == null || page.getContent() == null) {
            return "";
        }

        String pageContent = page.getContent();

        // If there are no bank transaction tables, return the full content
        if (page.getTables() == null || page.getTables().isEmpty()) {
            return pageContent;
        }

        // Get the content excluding bank transaction tables
        StringBuilder resultContent = new StringBuilder(pageContent);

        // Create a list of tables and sort them by spanOffset in reverse order
        List<Table> tables = new ArrayList<>(page.getTables().values());
        tables.sort(Comparator.comparingInt(Table::getSpanOffset).reversed());

        // Process tables from end to start
        for (Table table : tables) {
            if (table.isBankTransactions()) {
                int startIndex = table.getSpanOffset();
                int endIndex = startIndex + table.getSpanLength();

                // Remove the table content from the page content
                if (startIndex >= 0 && endIndex <= resultContent.length()) {
                    resultContent.delete(startIndex, endIndex);
                }
            }
        }

        return resultContent.toString().trim();
    }

    public static String generatePrompt(String context, String jsonSchema) {
        return "You are an expert information extraction assistant. Your task is to carefully analyze the provided context and extract specific pieces of information as per the keys defined in the given JSON schema. Once the information is extracted, you must format it into a valid JSON object with the actual values corresponding to the keys. Do not include any additional explanations, notes, or text outside the JSON object.\n\n" +
                "**Instructions:**\n" +
                "1. Read the provided context thoroughly. It is a text from bank statement\n" +
                "2. Identify the relevant information that matches the keys in the given JSON schema.\n" +
                "3. Extract the exact values for each key from the context.\n" +
                "4. Format the extracted information into a valid JSON object.\n" +
                "5. Ensure the JSON object strictly adheres to the structure and keys defined in the schema.\n" +
                "6. Return only the JSON object. Do not include any other text, explanations, or comments.\n\n" +
                "7. For date field always return date in dd/MM/yyyy format. if you find date with two character year then use 20 prefix for year example : 01/03/19 converted to 01/03/2019 \n" +
                "8. If you don't find any value for particular field then assign empty string for value."+
                "9. Double check information before forming the final json as there will be information about customer and bank for same field type example: customer address and bank address"+
                "10. If you find account_number field which has other alphabets characters then remove alphabets and any other special characters or spaces and then return account number" +
                "**Your Task:**\n\n" +
                "1. Context:\n" +
                context + "\n\n" +
                "2. JSON Schema:\n" +
                jsonSchema+"\n\n" +
                "**Output:**\n" +
                "[Return only the valid JSON object with extracted values. Do not include any other text or explanations. first character in response should be starting { ]";
    }

    public AccountSummary postProcessResponse(String response) {
        try {
            String jsonString = extractJsonString(response);
            if (jsonString == null) {
               logger.info("No JSON content found");
                return null;
            }
            AccountSummary accountSummary = objectMapper.readValue(jsonString, AccountSummary.class);
            return accountSummary;

        }catch (Exception e) {
            logger.error("Error deserializing JSON: ", e);
        }
        return null;
    }



    public static String extractJsonString(String input) {
        if(input == null || input.isEmpty()) {
            return null;
        }
        // Pattern to match JSON content between curly braces, including nested structures
        Pattern pattern = Pattern.compile("\\{(?:[^{}]|(?:\\{[^{}]*\\}))*\\}");
        Matcher matcher = pattern.matcher(input);

        if (matcher.find()) {
            return matcher.group();
        }

        return null; // Return null if no JSON is found
    }


}

