package com.finboost.bank.statement.parser.representation.document.extraction;

/**
 * Indicates which transaction table extraction engine produced the data for a statement / account.
 *
 * <ul>
 *     <li>{@link #NATIVE} - the offline native table extraction succeeded, no remote ML
 *     extraction was invoked.</li>
 *     <li>{@link #ML} - the remote ML document extraction was used directly because the bank
 *     format family has no supported native layout policy.</li>
 *     <li>{@link #NATIVE_FALLBACK_ML} - a native layout policy existed and was attempted but did
 *     not produce a usable transaction table, so the remote ML extraction was used instead.</li>
 * </ul>
 */
public enum TransactionExtractionMode {

    NATIVE,
    ML,
    NATIVE_FALLBACK_ML;

    public boolean isNative() {
        return this == NATIVE;
    }

    public boolean usedMl() {
        return this == ML || this == NATIVE_FALLBACK_ML;
    }

    /**
     * Aggregates the modes of several statements belonging to the same account.
     * Mixed results are reported as {@link #NATIVE_FALLBACK_ML} because part of the account data
     * still required the remote ML extraction.
     */
    public static TransactionExtractionMode merge(TransactionExtractionMode first, TransactionExtractionMode second) {
        if (first == null) {
            return second;
        }
        if (second == null) {
            return first;
        }
        if (first == second) {
            return first;
        }
        return NATIVE_FALLBACK_ML;
    }
}

package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

/**
 * Diagnostics captured while trying to extract the transaction table natively (offline).
 * The information is surfaced on API objects and persisted with the request logs so that the
 * native / ML routing of every statement can be audited afterwards.
 */
@Data
@AllArgsConstructor
@NoArgsConstructor
public class NativeExtractionDiagnostics {

    /** Bank format family (bank code) the native policy was resolved for. */
    private String bankFormatFamily;

    /** {@code true} when a native policy existed for the bank format family and was executed. */
    private boolean attempted;

    /** {@code true} when one of the native layouts produced a usable transaction table. */
    private boolean succeeded;

    /** Layout that produced the accepted result, {@code null} when nothing was accepted. */
    private NativeTableLayout selectedLayout;

    /** All layouts that were executed, in policy order. */
    private List<NativeTableLayout> attemptedLayouts = new LinkedList<>();

    /** Number of tables detected natively. */
    private int nativeTableCount;

    /** Number of transaction rows detected natively. */
    private int nativeRowCount;

    /** Reason why the native path was skipped or rejected. */
    private String skipOrFailureReason;

    public static NativeExtractionDiagnostics notAttempted(String bankFormatFamily, String reason) {
        NativeExtractionDiagnostics diagnostics = new NativeExtractionDiagnostics();
        diagnostics.setBankFormatFamily(bankFormatFamily);
        diagnostics.setAttempted(false);
        diagnostics.setSucceeded(false);
        diagnostics.setSkipOrFailureReason(reason);
        return diagnostics;
    }

    public void addAttemptedLayout(NativeTableLayout layout) {
        if (layout == null) {
            return;
        }
        if (this.attemptedLayouts == null) {
            this.attemptedLayouts = new LinkedList<>();
        }
        if (!this.attemptedLayouts.contains(layout)) {
            this.attemptedLayouts.add(layout);
        }
    }

    public NativeExtractionDiagnostics copy() {
        return new NativeExtractionDiagnostics(
                this.bankFormatFamily,
                this.attempted,
                this.succeeded,
                this.selectedLayout,
                this.attemptedLayouts == null ? new LinkedList<>() : new ArrayList<>(this.attemptedLayouts),
                this.nativeTableCount,
                this.nativeRowCount,
                this.skipOrFailureReason
        );
    }
}

