package com.finboost.bank.statement.parser.service.document.extraction.nativetable.geometry;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * A single axis aligned ruling (a stroked line or a very thin filled rectangle) of a PDF page.
 *
 * <p>All values are expressed in inches with the origin at the top-left corner of the page, which
 * is the same coordinate space used by {@link com.finboost.bank.statement.parser.representation.document.extraction.Word}.</p>
 *
 * <p>For a horizontal ruling {@code position} is the {@code y} coordinate and
 * {@code start}/{@code end} are the {@code x} extent. For a vertical ruling {@code position} is the
 * {@code x} coordinate and {@code start}/{@code end} are the {@code y} extent.</p>
 */
@Data
@AllArgsConstructor
@NoArgsConstructor
public class NativeRuling {

    private boolean horizontal;
    private float position;
    private float start;
    private float end;

    public float length() {
        return Math.abs(end - start);
    }

    public boolean covers(float from, float to, float minimumOverlapRatio) {
        float overlap = Math.min(end, Math.max(from, to)) - Math.max(start, Math.min(from, to));
        float span = Math.abs(to - from);
        if (span <= 0f) {
            return overlap >= 0f;
        }
        return (overlap / span) >= minimumOverlapRatio;
    }

    /** Merges another collinear ruling into this one by widening the extent. */
    public void mergeExtent(NativeRuling other) {
        if (other == null) {
            return;
        }
        this.start = Math.min(this.start, other.start);
        this.end = Math.max(this.end, other.end);
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.geometry;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * An axis aligned rectangle drawn on a PDF page (a filled cell background, a shaded header band or
 * a stroked box). Coordinates are in inches with the origin at the top-left of the page.
 */
@Data
@AllArgsConstructor
@NoArgsConstructor
public class NativeBox {

    private float left;
    private float top;
    private float right;
    private float bottom;
    private boolean filled;

    public float width() {
        return Math.abs(right - left);
    }

    public float height() {
        return Math.abs(bottom - top);
    }

    public float centerY() {
        return (top + bottom) / 2f;
    }

    public boolean containsY(float y) {
        return y >= top && y <= bottom;
    }

    public boolean verticallyOverlaps(NativeBox other, float tolerance) {
        if (other == null) {
            return false;
        }
        return this.top - tolerance <= other.bottom && other.top - tolerance <= this.bottom;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.geometry;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.Data;

import java.util.LinkedList;
import java.util.List;

/**
 * Everything the native table builders need from a single PDF page: the words with their polygons,
 * the axis aligned rulings and the drawn boxes. All coordinates are in inches with the origin at the
 * top-left corner of the page, matching the coordinate space of the ML extraction result.
 */
@Data
public class NativePageGeometry {

    private int pageNumber;
    private float width;
    private float height;
    private List<Word> words = new LinkedList<>();
    private List<NativeRuling> horizontalRulings = new LinkedList<>();
    private List<NativeRuling> verticalRulings = new LinkedList<>();
    private List<NativeBox> boxes = new LinkedList<>();
    private String textContent = "";

    public boolean hasWords() {
        return words != null && !words.isEmpty();
    }

    public boolean hasRulingGrid() {
        return horizontalRulings != null && verticalRulings != null
                && horizontalRulings.size() >= 2 && verticalRulings.size() >= 2;
    }

    public boolean hasBoxes() {
        return boxes != null && !boxes.isEmpty();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.geometry;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;
import org.apache.pdfbox.text.PDFTextStripper;
import org.apache.pdfbox.text.TextPosition;
import org.springframework.stereotype.Service;

import java.awt.geom.Point2D;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Offline, PDFBox based extractor that reads the geometry of an electronic PDF page:
 * words (grouped from glyphs), axis aligned rulings and drawn boxes.
 *
 * <p>This class performs no network access at all - it is the foundation of the native transaction
 * table path which replaces the remote ML extraction for the supported bank format families.</p>
 *
 * <p>All emitted coordinates are in inches with the origin at the top-left corner of the page crop
 * box, exactly matching the coordinate space produced by the remote ML response mapper, so that the
 * existing post processors can consume a native result unchanged.</p>
 */
@Service
@Slf4j
public class NativePdfGeometryExtractor {

    private static final float POINTS_PER_INCH = 72.0f;

    /** A filled rectangle thinner than this is considered a ruling instead of a box. */
    private static final float MAX_RULING_THICKNESS_POINTS = 2.5f;

    /** Rulings shorter than this are ignored (glyph decorations, bullet marks, ...). */
    private static final float MIN_RULING_LENGTH_POINTS = 4.0f;

    /** Tolerance used to decide that a segment is axis aligned. */
    private static final float AXIS_TOLERANCE_POINTS = 0.75f;

    /**
     * Reads the geometry of the given document.
     *
     * @param document  an already opened (and decrypted) PDF document
     * @param maxPages  maximum number of pages to read, {@code <= 0} reads every page
     * @return the geometry of every processed page, ordered by page number
     */
    public List<NativePageGeometry> extract(PDDocument document, int maxPages) throws IOException {
        List<NativePageGeometry> geometries = new LinkedList<>();
        if (document == null) {
            return geometries;
        }

        int pageCount = document.getNumberOfPages();
        int limit = maxPages > 0 ? Math.min(maxPages, pageCount) : pageCount;

        for (int pageIndex = 0; pageIndex < limit; pageIndex++) {
            PDPage page = document.getPage(pageIndex);
            if (isRotated(page)) {
                // rotated pages are not supported natively, the caller falls back to ML extraction
                log.debug("Native geometry extraction skipped for rotated page {}", pageIndex + 1);
                return new LinkedList<>();
            }
            geometries.add(extractPage(document, page, pageIndex));
        }
        return geometries;
    }

    private boolean isRotated(PDPage page) {
        int rotation = page.getRotation() % 360;
        return rotation != 0;
    }

    private NativePageGeometry extractPage(PDDocument document, PDPage page, int pageIndex) throws IOException {
        PDRectangle cropBox = page.getCropBox();

        NativePageGeometry geometry = new NativePageGeometry();
        geometry.setPageNumber(pageIndex + 1);
        geometry.setWidth(toInches(cropBox.getWidth()));
        geometry.setHeight(toInches(cropBox.getHeight()));

        VectorGeometryCollector collector = new VectorGeometryCollector(page, cropBox);
        try {
            collector.processPage(page);
        } catch (Exception e) {
            log.debug("Unable to read vector geometry of page {}: {}", pageIndex + 1, e.getMessage());
        }
        geometry.setHorizontalRulings(mergeRulings(collector.getHorizontalRulings()));
        geometry.setVerticalRulings(mergeRulings(collector.getVerticalRulings()));
        geometry.setBoxes(collector.getBoxes());

        GlyphCollector glyphCollector = new GlyphCollector();
        glyphCollector.setSortByPosition(true);
        glyphCollector.setStartPage(pageIndex + 1);
        glyphCollector.setEndPage(pageIndex + 1);
        String pageText = glyphCollector.getText(document);
        geometry.setTextContent(pageText == null ? "" : pageText);
        geometry.setWords(buildWords(glyphCollector.getGlyphs(), pageIndex + 1));

        return geometry;
    }

    // ------------------------------------------------------------------------------------------
    // word assembly
    // ------------------------------------------------------------------------------------------

    /**
     * Groups the collected glyphs into words. Glyphs are first clustered into text lines by vertical
     * overlap and then split into words on whitespace and on horizontal gaps wider than a fraction
     * of the font space width.
     */
    private List<Word> buildWords(List<Glyph> glyphs, int pageNumber) {
        List<Word> words = new LinkedList<>();
        if (glyphs == null || glyphs.isEmpty()) {
            return words;
        }

        List<Glyph> sorted = new ArrayList<>(glyphs);
        sorted.sort(Comparator.comparing((Glyph g) -> g.top).thenComparing(g -> g.left));

        List<List<Glyph>> lines = new LinkedList<>();
        List<Glyph> currentLine = new LinkedList<>();
        float lineTop = 0f;
        float lineBottom = 0f;

        for (Glyph glyph : sorted) {
            if (currentLine.isEmpty()) {
                currentLine.add(glyph);
                lineTop = glyph.top;
                lineBottom = glyph.bottom;
                continue;
            }
            float overlap = Math.min(lineBottom, glyph.bottom) - Math.max(lineTop, glyph.top);
            float reference = Math.max(0.001f, Math.min(lineBottom - lineTop, glyph.bottom - glyph.top));
            if (overlap >= 0.4f * reference) {
                currentLine.add(glyph);
                lineTop = Math.min(lineTop, glyph.top);
                lineBottom = Math.max(lineBottom, glyph.bottom);
            } else {
                lines.add(currentLine);
                currentLine = new LinkedList<>();
                currentLine.add(glyph);
                lineTop = glyph.top;
                lineBottom = glyph.bottom;
            }
        }
        if (!currentLine.isEmpty()) {
            lines.add(currentLine);
        }

        for (List<Glyph> line : lines) {
            words.addAll(buildWordsOfLine(line, pageNumber));
        }
        return words;
    }

    private List<Word> buildWordsOfLine(List<Glyph> line, int pageNumber) {
        List<Word> words = new LinkedList<>();
        List<Glyph> sorted = new ArrayList<>(line);
        sorted.sort(Comparator.comparing((Glyph g) -> g.left));

        List<Glyph> pending = new LinkedList<>();
        Glyph previous = null;
        for (Glyph glyph : sorted) {
            if (glyph.isBlank()) {
                flushWord(pending, pageNumber, words);
                previous = null;
                continue;
            }
            if (previous != null) {
                float gapThreshold = Math.max(0.3f * previous.spaceWidth, 0.006f);
                if (glyph.left - previous.right > gapThreshold) {
                    flushWord(pending, pageNumber, words);
                }
            }
            pending.add(glyph);
            previous = glyph;
        }
        flushWord(pending, pageNumber, words);
        return words;
    }

    private void flushWord(List<Glyph> pending, int pageNumber, List<Word> target) {
        if (pending.isEmpty()) {
            return;
        }
        StringBuilder content = new StringBuilder();
        float left = Float.MAX_VALUE;
        float right = -Float.MAX_VALUE;
        float top = Float.MAX_VALUE;
        float bottom = -Float.MAX_VALUE;
        for (Glyph glyph : pending) {
            content.append(glyph.text);
            left = Math.min(left, glyph.left);
            right = Math.max(right, glyph.right);
            top = Math.min(top, glyph.top);
            bottom = Math.max(bottom, glyph.bottom);
        }
        pending.clear();

        String text = content.toString().trim();
        if (text.isEmpty()) {
            return;
        }

        Word word = new Word(text, left, top, right, top, right, bottom, left, bottom,
                pageNumber, right - left, bottom - top, pageNumber, 0);
        target.add(word);
    }

    // ------------------------------------------------------------------------------------------
    // ruling normalisation
    // ------------------------------------------------------------------------------------------

    /**
     * Collapses collinear rulings (same position within tolerance) into a single ruling whose extent
     * is the union of the merged extents. Statements frequently draw one grid line as many short
     * segments, one per cell.
     */
    List<NativeRuling> mergeRulings(List<NativeRuling> rulings) {
        List<NativeRuling> merged = new LinkedList<>();
        if (rulings == null || rulings.isEmpty()) {
            return merged;
        }
        List<NativeRuling> sorted = new ArrayList<>(rulings);
        sorted.sort(Comparator.comparing(NativeRuling::getPosition).thenComparing(NativeRuling::getStart));

        float tolerance = 0.02f; // ~1.5 pt
        for (NativeRuling ruling : sorted) {
            NativeRuling candidate = merged.isEmpty() ? null : merged.get(merged.size() - 1);
            if (candidate != null
                    && Math.abs(candidate.getPosition() - ruling.getPosition()) <= tolerance
                    && ruling.getStart() <= candidate.getEnd() + tolerance) {
                candidate.mergeExtent(ruling);
            } else {
                merged.add(new NativeRuling(ruling.isHorizontal(), ruling.getPosition(), ruling.getStart(), ruling.getEnd()));
            }
        }
        return merged;
    }

    private static float toInches(float points) {
        return points / POINTS_PER_INCH;
    }

    // ------------------------------------------------------------------------------------------
    // helpers
    // ------------------------------------------------------------------------------------------

    /** A single glyph with its bounding box in inches, origin top-left. */
    private static final class Glyph {
        private final String text;
        private final float left;
        private final float right;
        private final float top;
        private final float bottom;
        private final float spaceWidth;

        private Glyph(String text, float left, float right, float top, float bottom, float spaceWidth) {
            this.text = text;
            this.left = left;
            this.right = right;
            this.top = top;
            this.bottom = bottom;
            this.spaceWidth = spaceWidth;
        }

        private boolean isBlank() {
            return text == null || text.trim().isEmpty();
        }
    }

    /** Collects the glyphs of a single page without altering the shared text extraction behaviour. */
    private static final class GlyphCollector extends PDFTextStripper {

        private final List<Glyph> glyphs = new LinkedList<>();

        private GlyphCollector() throws IOException {
            super();
        }

        private List<Glyph> getGlyphs() {
            return glyphs;
        }

        @Override
        protected void processTextPosition(TextPosition text) {
            String unicode = text.getUnicode();
            if (unicode == null || unicode.isEmpty()) {
                return;
            }
            float bottom = toInches(text.getYDirAdj());
            float height = toInches(text.getHeightDir());
            float left = toInches(text.getXDirAdj());
            float width = toInches(text.getWidthDirAdj());
            float spaceWidth = toInches(Math.max(text.getWidthOfSpace(), 1.0f));
            glyphs.add(new Glyph(unicode, left, left + width, bottom - height, bottom, spaceWidth));
        }
    }

    /**
     * Collects axis aligned rulings and boxes from the content stream of a page.
     * Thin filled rectangles are reported as rulings because many statements draw the grid that way.
     */
    private static final class VectorGeometryCollector extends PDFGraphicsStreamEngine {

        private final float cropLeft;
        private final float cropTop;
        private final List<NativeRuling> horizontalRulings = new LinkedList<>();
        private final List<NativeRuling> verticalRulings = new LinkedList<>();
        private final List<NativeBox> boxes = new LinkedList<>();
        private final List<float[]> pendingRectangles = new LinkedList<>();
        private final List<float[]> pendingSegments = new LinkedList<>();
        private Point2D currentPoint;
        private Point2D subPathStart;

        private VectorGeometryCollector(PDPage page, PDRectangle cropBox) {
            super(page);
            this.cropLeft = cropBox.getLowerLeftX();
            this.cropTop = cropBox.getUpperRightY();
        }

        private List<NativeRuling> getHorizontalRulings() {
            return horizontalRulings;
        }

        private List<NativeRuling> getVerticalRulings() {
            return verticalRulings;
        }

        private List<NativeBox> getBoxes() {
            return boxes;
        }

        @Override
        public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) {
            float minX = (float) Math.min(Math.min(p0.getX(), p1.getX()), Math.min(p2.getX(), p3.getX()));
            float maxX = (float) Math.max(Math.max(p0.getX(), p1.getX()), Math.max(p2.getX(), p3.getX()));
            float minY = (float) Math.min(Math.min(p0.getY(), p1.getY()), Math.min(p2.getY(), p3.getY()));
            float maxY = (float) Math.max(Math.max(p0.getY(), p1.getY()), Math.max(p2.getY(), p3.getY()));
            pendingRectangles.add(new float[]{minX, minY, maxX, maxY});
            currentPoint = new Point2D.Float(minX, minY);
        }

        @Override
        public void drawImage(PDImage pdImage) {
            // images carry no table geometry
        }

        @Override
        public void clip(int windingRule) {
            // clipping paths are not table geometry
        }

        @Override
        public void moveTo(float x, float y) {
            currentPoint = new Point2D.Float(x, y);
            subPathStart = currentPoint;
        }

        @Override
        public void lineTo(float x, float y) {
            if (currentPoint != null) {
                pendingSegments.add(new float[]{(float) currentPoint.getX(), (float) currentPoint.getY(), x, y});
            }
            currentPoint = new Point2D.Float(x, y);
        }

        @Override
        public void curveTo(float x1, float y1, float x2, float y2, float x3, float y3) {
            currentPoint = new Point2D.Float(x3, y3);
        }

        @Override
        public Point2D getCurrentPoint() {
            return currentPoint == null ? new Point2D.Float(0, 0) : currentPoint;
        }

        @Override
        public void closePath() {
            if (currentPoint != null && subPathStart != null) {
                pendingSegments.add(new float[]{(float) currentPoint.getX(), (float) currentPoint.getY(),
                        (float) subPathStart.getX(), (float) subPathStart.getY()});
                currentPoint = subPathStart;
            }
        }

        @Override
        public void endPath() {
            reset();
        }

        @Override
        public void strokePath() {
            for (float[] rectangle : pendingRectangles) {
                addRectangleEdges(rectangle);
            }
            for (float[] segment : pendingSegments) {
                addSegment(segment);
            }
            reset();
        }

        @Override
        public void fillPath(int windingRule) {
            fill();
            reset();
        }

        @Override
        public void fillAndStrokePath(int windingRule) {
            for (float[] rectangle : pendingRectangles) {
                addRectangleEdges(rectangle);
            }
            for (float[] segment : pendingSegments) {
                addSegment(segment);
            }
            fill();
            reset();
        }

        @Override
        public void shadingFill(COSName shadingName) {
            // gradient fills carry no reliable table geometry
        }

        private void fill() {
            for (float[] rectangle : pendingRectangles) {
                float width = rectangle[2] - rectangle[0];
                float height = rectangle[3] - rectangle[1];
                if (Math.min(width, height) <= MAX_RULING_THICKNESS_POINTS) {
                    // a thin filled rectangle is a drawn grid line
                    addThinRectangleAsRuling(rectangle, width, height);
                } else {
                    boxes.add(new NativeBox(toX(rectangle[0]), toY(rectangle[3]), toX(rectangle[2]), toY(rectangle[1]), true));
                }
            }
            if (!pendingSegments.isEmpty()) {
                float minX = Float.MAX_VALUE;
                float maxX = -Float.MAX_VALUE;
                float minY = Float.MAX_VALUE;
                float maxY = -Float.MAX_VALUE;
                for (float[] segment : pendingSegments) {
                    minX = Math.min(minX, Math.min(segment[0], segment[2]));
                    maxX = Math.max(maxX, Math.max(segment[0], segment[2]));
                    minY = Math.min(minY, Math.min(segment[1], segment[3]));
                    maxY = Math.max(maxY, Math.max(segment[1], segment[3]));
                }
                float width = maxX - minX;
                float height = maxY - minY;
                if (Math.min(width, height) <= MAX_RULING_THICKNESS_POINTS) {
                    addThinRectangleAsRuling(new float[]{minX, minY, maxX, maxY}, width, height);
                } else {
                    boxes.add(new NativeBox(toX(minX), toY(maxY), toX(maxX), toY(minY), true));
                }
            }
        }

        private void addThinRectangleAsRuling(float[] rectangle, float width, float height) {
            if (width >= height) {
                float centerY = (rectangle[1] + rectangle[3]) / 2f;
                addRuling(true, toY(centerY), toX(rectangle[0]), toX(rectangle[2]), width);
            } else {
                float centerX = (rectangle[0] + rectangle[2]) / 2f;
                addRuling(false, toX(centerX), toY(rectangle[3]), toY(rectangle[1]), height);
            }
        }

        private void addRectangleEdges(float[] rectangle) {
            float width = rectangle[2] - rectangle[0];
            float height = rectangle[3] - rectangle[1];
            if (Math.min(width, height) <= MAX_RULING_THICKNESS_POINTS) {
                addThinRectangleAsRuling(rectangle, width, height);
                return;
            }
            addRuling(true, toY(rectangle[1]), toX(rectangle[0]), toX(rectangle[2]), width);
            addRuling(true, toY(rectangle[3]), toX(rectangle[0]), toX(rectangle[2]), width);
            addRuling(false, toX(rectangle[0]), toY(rectangle[3]), toY(rectangle[1]), height);
            addRuling(false, toX(rectangle[2]), toY(rectangle[3]), toY(rectangle[1]), height);
        }

        private void addSegment(float[] segment) {
            float dx = Math.abs(segment[2] - segment[0]);
            float dy = Math.abs(segment[3] - segment[1]);
            if (dy <= AXIS_TOLERANCE_POINTS && dx > AXIS_TOLERANCE_POINTS) {
                float y = (segment[1] + segment[3]) / 2f;
                addRuling(true, toY(y), toX(Math.min(segment[0], segment[2])), toX(Math.max(segment[0], segment[2])), dx);
            } else if (dx <= AXIS_TOLERANCE_POINTS && dy > AXIS_TOLERANCE_POINTS) {
                float x = (segment[0] + segment[2]) / 2f;
                addRuling(false, toX(x), toY(Math.max(segment[1], segment[3])), toY(Math.min(segment[1], segment[3])), dy);
            }
        }

        private void addRuling(boolean horizontal, float position, float start, float end, float lengthInPoints) {
            if (lengthInPoints < MIN_RULING_LENGTH_POINTS) {
                return;
            }
            NativeRuling ruling = new NativeRuling(horizontal, position, Math.min(start, end), Math.max(start, end));
            if (horizontal) {
                horizontalRulings.add(ruling);
            } else {
                verticalRulings.add(ruling);
            }
        }

        private void reset() {
            pendingRectangles.clear();
            pendingSegments.clear();
            subPathStart = null;
        }

        private float toX(float x) {
            return (x - cropLeft) / POINTS_PER_INCH;
        }

        private float toY(float y) {
            return (cropTop - y) / POINTS_PER_INCH;
        }
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.Getter;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;
import java.util.stream.Collectors;

/**
 * A horizontal band of words that belong to the same visual text line of a PDF page.
 */
@Getter
public class NativeTextLine {

    private final List<Word> words = new LinkedList<>();
    private float top = Float.MAX_VALUE;
    private float bottom = -Float.MAX_VALUE;
    private float left = Float.MAX_VALUE;
    private float right = -Float.MAX_VALUE;

    public void add(Word word) {
        if (word == null) {
            return;
        }
        words.add(word);
        top = Math.min(top, NativeGeometryMath.top(word));
        bottom = Math.max(bottom, NativeGeometryMath.bottom(word));
        left = Math.min(left, NativeGeometryMath.left(word));
        right = Math.max(right, NativeGeometryMath.right(word));
    }

    public boolean isEmpty() {
        return words.isEmpty();
    }

    public float height() {
        return Math.max(0f, bottom - top);
    }

    public float centerY() {
        return (top + bottom) / 2f;
    }

    /** Words of the line ordered left to right. */
    public List<Word> orderedWords() {
        List<Word> ordered = new ArrayList<>(words);
        ordered.sort(Comparator.comparing(NativeGeometryMath::left));
        return ordered;
    }

    /** Text of the line with the words joined left to right by a single space. */
    public String text() {
        return orderedWords().stream()
                .map(Word::getContent)
                .filter(content -> content != null && !content.isEmpty())
                .collect(Collectors.joining(" "))
                .trim();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;

/**
 * Small geometry helpers shared by the native layout builders. Word polygons are stored as
 * {@code (x1,y1)} top-left, {@code (x2,y2)} top-right, {@code (x3,y3)} bottom-right,
 * {@code (x4,y4)} bottom-left, but the helpers stay tolerant to differently ordered polygons.
 */
public final class NativeGeometryMath {

    private NativeGeometryMath() {
    }

    public static float left(Word word) {
        return min(word.getX1(), word.getX2(), word.getX3(), word.getX4());
    }

    public static float right(Word word) {
        return max(word.getX1(), word.getX2(), word.getX3(), word.getX4());
    }

    public static float top(Word word) {
        return min(word.getY1(), word.getY2(), word.getY3(), word.getY4());
    }

    public static float bottom(Word word) {
        return max(word.getY1(), word.getY2(), word.getY3(), word.getY4());
    }

    public static float centerX(Word word) {
        return (left(word) + right(word)) / 2f;
    }

    public static float centerY(Word word) {
        return (top(word) + bottom(word)) / 2f;
    }

    private static float min(Float a, Float b, Float c, Float d) {
        return Math.min(Math.min(value(a), value(b)), Math.min(value(c), value(d)));
    }

    private static float max(Float a, Float b, Float c, Float d) {
        return Math.max(Math.max(negativeValue(a), negativeValue(b)), Math.max(negativeValue(c), negativeValue(d)));
    }

    private static float value(Float candidate) {
        return candidate == null ? Float.MAX_VALUE : candidate;
    }

    private static float negativeValue(Float candidate) {
        return candidate == null ? -Float.MAX_VALUE : candidate;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Groups words into visual text lines. Used by the box guided and the text aligned native layouts,
 * where rows are not delimited by rulings.
 */
public final class NativeTextLineAssembler {

    private NativeTextLineAssembler() {
    }

    /**
     * Groups the given words into text lines ordered top to bottom.
     *
     * @param words words of a single page
     */
    public static List<NativeTextLine> assemble(List<Word> words) {
        List<NativeTextLine> lines = new LinkedList<>();
        if (words == null || words.isEmpty()) {
            return lines;
        }

        List<Word> sorted = new ArrayList<>(words);
        sorted.sort(Comparator.comparing(NativeGeometryMath::top).thenComparing(NativeGeometryMath::left));

        NativeTextLine current = null;
        for (Word word : sorted) {
            if (current == null) {
                current = new NativeTextLine();
                current.add(word);
                continue;
            }
            float overlap = Math.min(current.getBottom(), NativeGeometryMath.bottom(word))
                    - Math.max(current.getTop(), NativeGeometryMath.top(word));
            float reference = Math.max(0.001f,
                    Math.min(current.height(), NativeGeometryMath.bottom(word) - NativeGeometryMath.top(word)));
            if (overlap >= 0.4f * reference) {
                current.add(word);
            } else {
                lines.add(current);
                current = new NativeTextLine();
                current.add(word);
            }
        }
        if (current != null && !current.isEmpty()) {
            lines.add(current);
        }
        return lines;
    }

    /** Restricts the given lines to the vertical window {@code [top, bottom]}. */
    public static List<NativeTextLine> within(List<NativeTextLine> lines, float top, float bottom) {
        List<NativeTextLine> selected = new LinkedList<>();
        if (lines == null) {
            return selected;
        }
        for (NativeTextLine line : lines) {
            if (line.centerY() >= top && line.centerY() <= bottom) {
                selected.add(line);
            }
        }
        return selected;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Recovers column boundaries from the horizontal alignment of words when the statement does not
 * draw vertical rulings.
 *
 * <p>The word intervals of all supplied rows are projected onto the x axis. The gaps in that
 * projection which are wide enough to be a column separator become the column boundaries, and each
 * boundary is placed in the middle of its gap.</p>
 */
public final class NativeColumnBoundaryDetector {

    /** Minimum white space (in inches) between two columns. */
    private static final float DEFAULT_MIN_GAP = 0.06f;

    private NativeColumnBoundaryDetector() {
    }

    public static List<Float> detect(List<List<Word>> rows) {
        return detect(rows, DEFAULT_MIN_GAP);
    }

    /**
     * @param rows    rows of words to project
     * @param minGap  minimum gap in inches that separates two columns
     * @return sorted column boundaries, size {@code columnCount + 1}; empty when nothing was found
     */
    public static List<Float> detect(List<List<Word>> rows, float minGap) {
        List<float[]> intervals = new LinkedList<>();
        if (rows == null) {
            return new LinkedList<>();
        }
        for (List<Word> row : rows) {
            if (row == null) {
                continue;
            }
            for (Word word : row) {
                intervals.add(new float[]{NativeGeometryMath.left(word), NativeGeometryMath.right(word)});
            }
        }
        if (intervals.isEmpty()) {
            return new LinkedList<>();
        }

        List<float[]> sorted = new ArrayList<>(intervals);
        sorted.sort(Comparator.comparingDouble(interval -> interval[0]));

        // merge overlapping / touching intervals into occupied bands
        List<float[]> bands = new LinkedList<>();
        float[] currentBand = new float[]{sorted.get(0)[0], sorted.get(0)[1]};
        for (int index = 1; index < sorted.size(); index++) {
            float[] interval = sorted.get(index);
            if (interval[0] - currentBand[1] < minGap) {
                currentBand[1] = Math.max(currentBand[1], interval[1]);
            } else {
                bands.add(currentBand);
                currentBand = new float[]{interval[0], interval[1]};
            }
        }
        bands.add(currentBand);

        List<Float> boundaries = new LinkedList<>();
        boundaries.add(bands.get(0)[0]);
        for (int index = 0; index < bands.size() - 1; index++) {
            float gapStart = bands.get(index)[1];
            float gapEnd = bands.get(index + 1)[0];
            boundaries.add((gapStart + gapEnd) / 2f);
        }
        boundaries.add(bands.get(bands.size() - 1)[1]);
        return boundaries;
    }

    /** Builds boundaries from explicit x positions, removing duplicates within tolerance. */
    public static List<Float> fromPositions(List<Float> positions, float tolerance) {
        List<Float> boundaries = new LinkedList<>();
        if (positions == null || positions.isEmpty()) {
            return boundaries;
        }
        List<Float> sorted = new ArrayList<>(positions);
        sorted.sort(Comparator.naturalOrder());
        for (Float position : sorted) {
            if (boundaries.isEmpty() || Math.abs(boundaries.get(boundaries.size() - 1) - position) > tolerance) {
                boundaries.add(position);
            }
        }
        return boundaries;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout;

import java.util.regex.Pattern;

/**
 * Light weight token patterns used only by the native layout builders to recognise the shape of a
 * transaction row (a leading date, monetary amounts, header keywords).
 *
 * <p>These patterns are deliberately kept local to the native path: the transaction and date parsing
 * behaviour of the existing pipeline is untouched, the native builders only use them to decide where
 * a row starts and where the table region is.</p>
 */
public final class NativeStatementPatterns {

    /** dd/MM/yyyy, dd-MM-yy, dd.MM.yyyy, yyyy-MM-dd, dd-MMM-yyyy, ddMMMyy ... */
    public static final Pattern DATE_TOKEN = Pattern.compile(
            "^(?:"
                    + "[0-3]?\\d[-/.\\s][0-1]?\\d[-/.\\s](?:\\d{2}|\\d{4})"
                    + "|\\d{4}[-/.][0-1]?\\d[-/.][0-3]?\\d"
                    + "|[0-3]?\\d[-/.\\s]?(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*[-/.\\s]?(?:\\d{2}|\\d{4})?"
                    + "|(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*[-/.\\s][0-3]?\\d[,-/.\\s]*(?:\\d{2}|\\d{4})?"
                    + ")[.,]?$",
            Pattern.CASE_INSENSITIVE);

    /** 1,234.56 / 1234.56 / 1234.56Cr / (1,234.56) / -1234.56 */
    public static final Pattern AMOUNT_TOKEN = Pattern.compile(
            "^[(\\-+]?(?:inr|rs\\.?|\\u20b9)?\\s*\\d{1,3}(?:,\\d{2,3})*(?:\\.\\d{1,4})?\\s*(?:cr|dr|c|d)?[)\\-+]?$",
            Pattern.CASE_INSENSITIVE);

    /** Keywords that identify the header line of a transaction table. */
    public static final Pattern HEADER_TOKEN = Pattern.compile(
            "(date|narration|particular|description|detail|remark|withdrawal|withdrawl|deposit|debit|credit"
                    + "|balance|amount|cheque|chq|ref|instrument|value|type|dr\\s*/?\\s*cr)",
            Pattern.CASE_INSENSITIVE);

    private NativeStatementPatterns() {
    }

    public static boolean isDateToken(String token) {
        if (token == null) {
            return false;
        }
        String trimmed = token.trim();
        if (trimmed.length() < 5) {
            return false;
        }
        return DATE_TOKEN.matcher(trimmed).matches();
    }

    public static boolean isAmountToken(String token) {
        if (token == null) {
            return false;
        }
        String trimmed = token.trim();
        if (trimmed.isEmpty()) {
            return false;
        }
        if (!trimmed.matches(".*\\d.*")) {
            return false;
        }
        return AMOUNT_TOKEN.matcher(trimmed).matches();
    }

    /** Counts how many distinct header keywords the given line text contains. */
    public static int headerKeywordCount(String text) {
        if (text == null || text.isBlank()) {
            return 0;
        }
        int count = 0;
        java.util.regex.Matcher matcher = HEADER_TOKEN.matcher(text);
        java.util.Set<String> seen = new java.util.HashSet<>();
        while (matcher.find()) {
            if (seen.add(matcher.group(1).toLowerCase())) {
                count++;
            }
        }
        return count;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.Data;

import java.util.LinkedList;
import java.util.List;

/**
 * One assembled native table row: its vertical band and the words that belong to it.
 */
@Data
public class NativeTableRow {

    private float top;
    private float bottom;
    private boolean headerRow;
    private List<Word> words = new LinkedList<>();

    public NativeTableRow(float top, float bottom) {
        this.top = top;
        this.bottom = bottom;
    }

    public void addWords(List<Word> additional) {
        if (additional == null || additional.isEmpty()) {
            return;
        }
        words.addAll(additional);
    }

    public void mergeWith(NativeTableRow other) {
        if (other == null) {
            return;
        }
        this.top = Math.min(this.top, other.top);
        this.bottom = Math.max(this.bottom, other.bottom);
        addWords(other.getWords());
    }

    public boolean isEmpty() {
        return words.isEmpty();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

/**
 * Turns column boundaries plus assembled rows into a
 * {@link com.finboost.bank.statement.parser.representation.document.extraction.Table} that is shaped
 * exactly like the one produced by the remote ML response mapper, so that every existing post
 * processor keeps working unchanged.
 */
public final class NativeTableAssembler {

    private NativeTableAssembler() {
    }

    /**
     * @param pageNumber       1 based page number
     * @param columnBoundaries sorted x boundaries, {@code columnCount + 1} entries
     * @param rows             assembled rows ordered top to bottom
     */
    public static Table assemble(int pageNumber, List<Float> columnBoundaries, List<NativeTableRow> rows) {
        if (columnBoundaries == null || columnBoundaries.size() < 2 || rows == null || rows.isEmpty()) {
            return null;
        }

        int columnCount = columnBoundaries.size() - 1;
        Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();

        int rowIndex = 0;
        for (NativeTableRow row : rows) {
            Map<Integer, TableCell> rowCells = new LinkedHashMap<>();
            for (int columnIndex = 0; columnIndex < columnCount; columnIndex++) {
                float cellLeft = columnBoundaries.get(columnIndex);
                float cellRight = columnBoundaries.get(columnIndex + 1);
                List<Word> cellWords = new LinkedList<>();
                for (Word word : row.getWords()) {
                    float center = NativeGeometryMath.centerX(word);
                    boolean lastColumn = columnIndex == columnCount - 1;
                    if (center >= cellLeft && (center < cellRight || (lastColumn && center <= cellRight))) {
                        cellWords.add(word);
                    }
                }
                TableCell cell = buildCell(rowIndex, columnIndex, cellLeft, row.getTop(), cellRight, row.getBottom(), cellWords);
                cell.setHeaderOrFooterCell(row.isHeaderRow());
                rowCells.put(columnIndex, cell);
            }
            cells.put(rowIndex, rowCells);
            rowIndex++;
        }

        Table table = new Table();
        table.setPageNumber(pageNumber);
        float tableLeft = columnBoundaries.get(0);
        float tableRight = columnBoundaries.get(columnBoundaries.size() - 1);
        float tableTop = rows.get(0).getTop();
        float tableBottom = rows.get(rows.size() - 1).getBottom();
        table.setX1(tableLeft);
        table.setY1(tableTop);
        table.setX2(tableRight);
        table.setY2(tableTop);
        table.setX3(tableRight);
        table.setY3(tableBottom);
        table.setX4(tableLeft);
        table.setY4(tableBottom);
        table.setCells(cells);
        table.setTotalRows(cells.size());
        table.setTotalColumns(columnCount);
        table.setColType(new ArrayList<>());
        table.setTxnColType(new ArrayList<>());
        table.setSpanOffset(0);
        table.setSpanLength(0);
        table.setColumnBoundaries(new ArrayList<>(columnBoundaries));
        return table;
    }

    public static TableCell buildCell(int rowIndex, int columnIndex,
                                      float left, float top, float right, float bottom,
                                      List<Word> words) {
        TableCell cell = new TableCell();
        cell.setRowindex(rowIndex);
        cell.setColindex(columnIndex);
        cell.setRowspan(1);
        cell.setColspan(1);
        cell.setX1(left);
        cell.setY1(top);
        cell.setX2(right);
        cell.setY2(top);
        cell.setX3(right);
        cell.setY3(bottom);
        cell.setX4(left);
        cell.setY4(bottom);
        cell.setWords(words == null ? new LinkedList<>() : words);
        return cell;
    }

    /** Counts rows whose left most non empty cell content looks like a transaction date. */
    public static int countDateAnchoredRows(Table table) {
        if (table == null || table.getCells() == null) {
            return 0;
        }
        int count = 0;
        for (Map<Integer, TableCell> row : table.getCells().values()) {
            if (row == null || row.isEmpty()) {
                continue;
            }
            List<Integer> columnIndices = new ArrayList<>(row.keySet());
            columnIndices.sort(Integer::compareTo);
            for (Integer columnIndex : columnIndices) {
                TableCell cell = row.get(columnIndex);
                if (cell == null) {
                    continue;
                }
                String content = cell.getContent();
                if (content == null || content.isBlank()) {
                    continue;
                }
                if (NativeStatementPatterns.isDateToken(content)) {
                    count++;
                }
                break;
            }
        }
        return count;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.geometry.NativePageGeometry;

import java.util.List;

/**
 * Builds the transaction tables of a single page for one native layout.
 */
public interface NativeTableLayoutBuilder {

    /** The layout implemented by this builder. */
    NativeTableLayout layout();

    /**
     * Builds the candidate tables of a page.
     *
     * @return the detected tables, an empty list when the layout does not apply to the page
     */
    List<Table> buildTables(NativePageGeometry geometry);
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.geometry.NativePageGeometry;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.geometry.NativeRuling;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

/**
 * Native layout for statements that draw a complete ruling grid around every transaction cell
 * (the classic "lattice" layout used by most public sector bank statements).
 *
 * <p>Rows come from the horizontal rulings, columns from the vertical rulings. A boundary that is not
 * backed by a vertical ruling for a given row produces a spanned cell, exactly like the remote ML
 * extraction reports merged cells, so that {@code TableColumnNormalizer} can normalise them.</p>
 */
@Component
@Slf4j
public class BorderedGridTableLayoutBuilder implements NativeTableLayoutBuilder {

    /** Two rulings closer than this are the same grid line. */
    private static final float POSITION_TOLERANCE = 0.02f;

    /** Minimum width of a grid column in inches. */
    private static final float MIN_COLUMN_WIDTH = 0.07f;

    /** Minimum height of a grid row in inches. */
    private static final float MIN_ROW_HEIGHT = 0.045f;

    /** Vertical distance between two horizontal rulings that splits two separate grids. */
    private static final float MAX_GRID_ROW_GAP = 1.6f;

    /** A vertical ruling must cover at least this fraction of the grid height to be a column line. */
    private static final float MIN_COLUMN_COVERAGE = 0.45f;

    /** A vertical ruling must cover at least this fraction of a row to close a cell. */
    private static final float MIN_CELL_COVERAGE = 0.55f;

    /** Minimum number of columns for a candidate transaction grid. */
    private static final int MIN_COLUMNS = 3;

    @Override
    public NativeTableLayout layout() {
        return NativeTableLayout.BORDERED_GRID;
    }

    @Override
    public List<Table> buildTables(NativePageGeometry geometry) {
        List<Table> tables = new LinkedList<>();
        if (geometry == null || !geometry.hasWords() || !geometry.hasRulingGrid()) {
            return tables;
        }

        List<NativeRuling> horizontal = distinct(geometry.getHorizontalRulings());
        List<NativeRuling> vertical = distinct(geometry.getVerticalRulings());
        if (horizontal.size() < 2 || vertical.size() < 2) {
            return tables;
        }

        for (List<NativeRuling> grid : groupByContiguity(horizontal)) {
            Table table = buildGridTable(geometry, grid, vertical);
            if (table != null) {
                tables.add(table);
            }
        }
        return tables;
    }

    private Table buildGridTable(NativePageGeometry geometry, List<NativeRuling> gridRows, List<NativeRuling> vertical) {
        if (gridRows.size() < 2) {
            return null;
        }
        float gridTop = gridRows.get(0).getPosition();
        float gridBottom = gridRows.get(gridRows.size() - 1).getPosition();
        float gridHeight = gridBottom - gridTop;
        if (gridHeight <= MIN_ROW_HEIGHT) {
            return null;
        }

        List<NativeRuling> columnRulings = new LinkedList<>();
        for (NativeRuling ruling : vertical) {
            if (ruling.covers(gridTop, gridBottom, MIN_COLUMN_COVERAGE)) {
                columnRulings.add(ruling);
            }
        }
        List<Float> columnBoundaries = boundariesOf(columnRulings);
        if (columnBoundaries.size() < MIN_COLUMNS + 1) {
            return null;
        }

        List<Float> rowBoundaries = new LinkedList<>();
        for (NativeRuling ruling : gridRows) {
            if (rowBoundaries.isEmpty()
                    || ruling.getPosition() - rowBoundaries.get(rowBoundaries.size() - 1) > MIN_ROW_HEIGHT) {
                rowBoundaries.add(ruling.getPosition());
            }
        }
        if (rowBoundaries.size() < 2) {
            return null;
        }

        float left = columnBoundaries.get(0);
        float right = columnBoundaries.get(columnBoundaries.size() - 1);
        List<Word> gridWords = wordsWithin(geometry.getWords(), left, gridTop, right, gridBottom);
        if (gridWords.isEmpty()) {
            return null;
        }

        Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();
        int rowIndex = 0;
        float tableTop = Float.MAX_VALUE;
        float tableBottom = -Float.MAX_VALUE;
        for (int band = 0; band < rowBoundaries.size() - 1; band++) {
            float rowTop = rowBoundaries.get(band);
            float rowBottom = rowBoundaries.get(band + 1);
            Map<Integer, TableCell> rowCells = buildRowCells(rowIndex, rowTop, rowBottom, columnBoundaries,
                    columnRulings, gridWords);
            if (rowCells.isEmpty() || isBlankRow(rowCells)) {
                continue;
            }
            cells.put(rowIndex, rowCells);
            tableTop = Math.min(tableTop, rowTop);
            tableBottom = Math.max(tableBottom, rowBottom);
            rowIndex++;
        }
        if (cells.isEmpty()) {
            return null;
        }

        Table table = new Table();
        table.setPageNumber(geometry.getPageNumber());
        table.setX1(left);
        table.setY1(tableTop);
        table.setX2(right);
        table.setY2(tableTop);
        table.setX3(right);
        table.setY3(tableBottom);
        table.setX4(left);
        table.setY4(tableBottom);
        table.setCells(cells);
        table.setTotalRows(cells.size());
        table.setTotalColumns(columnBoundaries.size() - 1);
        table.setColType(new ArrayList<>());
        table.setTxnColType(new ArrayList<>());
        table.setSpanOffset(0);
        table.setSpanLength(0);
        table.setColumnBoundaries(new ArrayList<>(columnBoundaries));
        return table;
    }

    /**
     * Builds the cells of one grid row. Boundaries without a supporting vertical ruling produce a
     * spanned cell.
     */
    private Map<Integer, TableCell> buildRowCells(int rowIndex, float rowTop, float rowBottom,
                                                 List<Float> columnBoundaries, List<NativeRuling> columnRulings,
                                                 List<Word> gridWords) {
        Map<Integer, TableCell> rowCells = new LinkedHashMap<>();
        int columnCount = columnBoundaries.size() - 1;

        int startColumn = 0;
        while (startColumn < columnCount) {
            int endColumn = startColumn;
            while (endColumn < columnCount - 1
                    && !hasVerticalRulingAt(columnRulings, columnBoundaries.get(endColumn + 1), rowTop, rowBottom)) {
                endColumn++;
            }
            float cellLeft = columnBoundaries.get(startColumn);
            float cellRight = columnBoundaries.get(endColumn + 1);
            boolean lastColumn = endColumn == columnCount - 1;
            List<Word> cellWords = new LinkedList<>();
            for (Word word : gridWords) {
                float centerX = NativeGeometryMath.centerX(word);
                float centerY = NativeGeometryMath.centerY(word);
                if (centerY < rowTop || centerY > rowBottom) {
                    continue;
                }
                if (centerX >= cellLeft && (centerX < cellRight || (lastColumn && centerX <= cellRight))) {
                    cellWords.add(word);
                }
            }
            TableCell cell = NativeTableAssembler.buildCell(rowIndex, startColumn, cellLeft, rowTop, cellRight,
                    rowBottom, cellWords);
            cell.setColspan(endColumn - startColumn + 1);
            rowCells.put(startColumn, cell);
            startColumn = endColumn + 1;
        }
        return rowCells;
    }

    private boolean hasVerticalRulingAt(List<NativeRuling> columnRulings, float position, float rowTop, float rowBottom) {
        for (NativeRuling ruling : columnRulings) {
            if (Math.abs(ruling.getPosition() - position) <= POSITION_TOLERANCE
                    && ruling.covers(rowTop, rowBottom, MIN_CELL_COVERAGE)) {
                return true;
            }
        }
        return false;
    }

    private boolean isBlankRow(Map<Integer, TableCell> rowCells) {
        for (TableCell cell : rowCells.values()) {
            String content = cell.getContent();
            if (content != null && !content.isBlank()) {
                return false;
            }
        }
        return true;
    }

    private List<Word> wordsWithin(List<Word> words, float left, float top, float right, float bottom) {
        List<Word> selected = new LinkedList<>();
        if (words == null) {
            return selected;
        }
        for (Word word : words) {
            float centerX = NativeGeometryMath.centerX(word);
            float centerY = NativeGeometryMath.centerY(word);
            if (centerX >= left - POSITION_TOLERANCE && centerX <= right + POSITION_TOLERANCE
                    && centerY >= top - POSITION_TOLERANCE && centerY <= bottom + POSITION_TOLERANCE) {
                selected.add(word);
            }
        }
        return selected;
    }

    private List<Float> boundariesOf(List<NativeRuling> columnRulings) {
        List<Float> positions = new LinkedList<>();
        List<NativeRuling> sorted = new ArrayList<>(columnRulings);
        sorted.sort(Comparator.comparing(NativeRuling::getPosition));
        for (NativeRuling ruling : sorted) {
            if (positions.isEmpty() || ruling.getPosition() - positions.get(positions.size() - 1) > MIN_COLUMN_WIDTH) {
                positions.add(ruling.getPosition());
            }
        }
        return positions;
    }

    private List<NativeRuling> distinct(List<NativeRuling> rulings) {
        List<NativeRuling> sorted = new ArrayList<>(rulings == null ? new LinkedList<>() : rulings);
        sorted.sort(Comparator.comparing(NativeRuling::getPosition));
        return sorted;
    }

    /** Splits the horizontal rulings of a page into separate grid candidates. */
    private List<List<NativeRuling>> groupByContiguity(List<NativeRuling> horizontal) {
        List<List<NativeRuling>> groups = new LinkedList<>();
        List<NativeRuling> current = new LinkedList<>();
        for (NativeRuling ruling : horizontal) {
            if (current.isEmpty()) {
                current.add(ruling);
                continue;
            }
            NativeRuling previous = current.get(current.size() - 1);
            if (ruling.getPosition() - previous.getPosition() <= MAX_GRID_ROW_GAP) {
                current.add(ruling);
            } else {
                groups.add(current);
                current = new LinkedList<>();
                current.add(ruling);
            }
        }
        if (!current.isEmpty()) {
            groups.add(current);
        }
        return groups;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.geometry.NativeBox;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.geometry.NativePageGeometry;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Native layout for statements that do not draw a full grid but do draw boxes: a shaded header band,
 * zebra striped row bands or one filled rectangle per cell.
 *
 * <p>The boxes are used as guides:</p>
 * <ul>
 *     <li>the union of the guide boxes gives the horizontal extent and the top of the table region;</li>
 *     <li>a band that consists of several side by side boxes gives the exact column boundaries;</li>
 *     <li>if no such band exists the column boundaries are recovered from the horizontal alignment of
 *     the text inside the region.</li>
 * </ul>
 *
 * <p>Rows are assembled from the text lines of the region, and continuation lines (wrapped
 * descriptions with an empty first column) are merged into the preceding row.</p>
 */
@Component
@Slf4j
public class BoxGuidedTableLayoutBuilder implements NativeTableLayoutBuilder {

    /** A guide box must be at least this fraction of the page width. */
    private static final float MIN_BOX_WIDTH_RATIO = 0.20f;

    /** A guide box taller than this is a page decoration, not a row band or a header band. */
    private static final float MAX_BAND_HEIGHT = 1.20f;

    /** Vertical tolerance when grouping boxes into a band. */
    private static final float BAND_TOLERANCE = 0.02f;

    /** Bottom margin kept free when a single header band has to be extended down the page. */
    private static final float PAGE_BOTTOM_MARGIN = 0.35f;

    /** Minimum number of columns for a candidate transaction table. */
    private static final int MIN_COLUMNS = 3;

    @Override
    public NativeTableLayout layout() {
        return NativeTableLayout.BOX_GUIDED;
    }

    @Override
    public List<Table> buildTables(NativePageGeometry geometry) {
        List<Table> tables = new LinkedList<>();
        if (geometry == null || !geometry.hasWords() || !geometry.hasBoxes()) {
            return tables;
        }

        List<NativeBox> guides = guideBoxes(geometry);
        if (guides.isEmpty()) {
            return tables;
        }

        float regionLeft = Float.MAX_VALUE;
        float regionRight = -Float.MAX_VALUE;
        float regionTop = Float.MAX_VALUE;
        float regionBottom = -Float.MAX_VALUE;
        for (NativeBox box : guides) {
            regionLeft = Math.min(regionLeft, box.getLeft());
            regionRight = Math.max(regionRight, box.getRight());
            regionTop = Math.min(regionTop, box.getTop());
            regionBottom = Math.max(regionBottom, box.getBottom());
        }

        List<List<NativeBox>> bands = groupIntoBands(guides);
        if (bands.size() < 3) {
            // a single (header) band only guides the top of the table, the rows continue below it
            regionBottom = Math.max(regionBottom, geometry.getHeight() - PAGE_BOTTOM_MARGIN);
        }

        List<NativeTextLine> lines = NativeTextLineAssembler.within(
                NativeTextLineAssembler.assemble(geometry.getWords()), regionTop, regionBottom);
        lines = restrictHorizontally(lines, regionLeft, regionRight);
        if (lines.size() < 2) {
            return tables;
        }

        List<Float> columnBoundaries = columnBoundariesFromBands(bands);
        if (columnBoundaries.size() < MIN_COLUMNS + 1) {
            List<List<Word>> rowsOfWords = new LinkedList<>();
            for (NativeTextLine line : lines) {
                rowsOfWords.add(line.orderedWords());
            }
            columnBoundaries = NativeColumnBoundaryDetector.detect(rowsOfWords);
        }
        if (columnBoundaries.size() < MIN_COLUMNS + 1) {
            return tables;
        }

        List<NativeTableRow> rows = NativeRowSelector.selectRows(lines, columnBoundaries);
        if (rows.size() < 2) {
            return tables;
        }

        Table table = NativeTableAssembler.assemble(geometry.getPageNumber(), columnBoundaries, rows);
        if (table != null) {
            tables.add(table);
        }
        return tables;
    }

    private List<NativeBox> guideBoxes(NativePageGeometry geometry) {
        float minWidth = MIN_BOX_WIDTH_RATIO * Math.max(geometry.getWidth(), 0.001f);
        List<NativeBox> guides = new LinkedList<>();
        for (NativeBox box : geometry.getBoxes()) {
            if (box.width() >= minWidth && box.height() <= MAX_BAND_HEIGHT && box.height() > 0.0f) {
                guides.add(box);
            }
        }
        guides.sort(Comparator.comparing(NativeBox::getTop).thenComparing(NativeBox::getLeft));
        return guides;
    }

    private List<List<NativeBox>> groupIntoBands(List<NativeBox> guides) {
        List<List<NativeBox>> bands = new LinkedList<>();
        List<NativeBox> current = new LinkedList<>();
        for (NativeBox box : guides) {
            if (current.isEmpty()) {
                current.add(box);
                continue;
            }
            if (Math.abs(current.get(0).getTop() - box.getTop()) <= BAND_TOLERANCE) {
                current.add(box);
            } else {
                bands.add(current);
                current = new LinkedList<>();
                current.add(box);
            }
        }
        if (!current.isEmpty()) {
            bands.add(current);
        }
        return bands;
    }

    /**
     * Uses the band with the highest number of side by side boxes as the column guide. Such a band is
     * the shaded header row (one box per header cell) of many statement formats.
     */
    private List<Float> columnBoundariesFromBands(List<List<NativeBox>> bands) {
        List<NativeBox> guideBand = null;
        for (List<NativeBox> band : bands) {
            if (band.size() >= MIN_COLUMNS && (guideBand == null || band.size() > guideBand.size())) {
                guideBand = band;
            }
        }
        if (guideBand == null) {
            return new LinkedList<>();
        }
        List<NativeBox> ordered = new ArrayList<>(guideBand);
        ordered.sort(Comparator.comparing(NativeBox::getLeft));
        List<Float> positions = new LinkedList<>();
        positions.add(ordered.get(0).getLeft());
        for (int index = 0; index < ordered.size() - 1; index++) {
            positions.add((ordered.get(index).getRight() + ordered.get(index + 1).getLeft()) / 2f);
        }
        positions.add(ordered.get(ordered.size() - 1).getRight());
        return NativeColumnBoundaryDetector.fromPositions(positions, 0.02f);
    }

    private List<NativeTextLine> restrictHorizontally(List<NativeTextLine> lines, float left, float right) {
        List<NativeTextLine> restricted = new LinkedList<>();
        for (NativeTextLine line : lines) {
            NativeTextLine trimmed = new NativeTextLine();
            for (Word word : line.orderedWords()) {
                float centerX = NativeGeometryMath.centerX(word);
                if (centerX >= left - 0.05f && centerX <= right + 0.05f) {
                    trimmed.add(word);
                }
            }
            if (!trimmed.isEmpty()) {
                restricted.add(trimmed);
            }
        }
        return restricted;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;

import java.util.LinkedList;
import java.util.List;

/**
 * Row selection rules shared by the native layouts that have to derive rows from text lines.
 */
public final class NativeRowSelector {

    /** How many leading lines of a region are inspected while looking for the header line. */
    private static final int HEADER_LOOKAHEAD = 3;

    /** Minimum number of distinct header keywords required to accept a line as the header line. */
    private static final int MIN_HEADER_KEYWORDS = 3;

    private NativeRowSelector() {
    }

    /**
     * Builds rows out of text lines. The header line (when present) becomes the first row, every line
     * with content in the first column starts a new row and every other line is a wrapped
     * continuation that is merged into the preceding row.
     */
    public static List<NativeTableRow> selectRows(List<NativeTextLine> lines, List<Float> columnBoundaries) {
        List<NativeTableRow> rows = new LinkedList<>();
        if (lines == null || lines.isEmpty() || columnBoundaries == null || columnBoundaries.size() < 2) {
            return rows;
        }

        float firstColumnLeft = columnBoundaries.get(0);
        float firstColumnRight = columnBoundaries.get(1);

        int headerIndex = findHeaderLineIndex(lines);
        NativeTableRow current = null;
        for (int index = 0; index < lines.size(); index++) {
            NativeTextLine line = lines.get(index);
            NativeTableRow row = toRow(line);
            if (index == headerIndex) {
                row.setHeaderRow(true);
                rows.add(row);
                current = null;
                continue;
            }
            if (index < headerIndex) {
                // content above the header line is not part of the table
                continue;
            }
            boolean startsRow = current == null || hasContentIn(line, firstColumnLeft, firstColumnRight);
            if (startsRow) {
                rows.add(row);
                current = row;
            } else {
                current.mergeWith(row);
            }
        }
        return rows;
    }

    /**
     * Selects the transaction rows of a page purely from the text: a row starts on a line whose left
     * most token is a date and which carries at least one monetary amount. Lines in between are
     * wrapped descriptions and are merged into the preceding row.
     */
    public static List<NativeTableRow> selectDateAnchoredRows(List<NativeTextLine> lines) {
        List<NativeTableRow> rows = new LinkedList<>();
        if (lines == null || lines.isEmpty()) {
            return rows;
        }

        int firstAnchor = -1;
        int lastAnchor = -1;
        for (int index = 0; index < lines.size(); index++) {
            if (isTransactionLine(lines.get(index))) {
                if (firstAnchor < 0) {
                    firstAnchor = index;
                }
                lastAnchor = index;
            }
        }
        if (firstAnchor < 0) {
            return rows;
        }

        int headerIndex = findHeaderLineIndexAbove(lines, firstAnchor);
        if (headerIndex >= 0) {
            NativeTableRow header = toRow(lines.get(headerIndex));
            header.setHeaderRow(true);
            rows.add(header);
        }

        NativeTableRow current = null;
        for (int index = firstAnchor; index <= lastAnchor; index++) {
            NativeTextLine line = lines.get(index);
            NativeTableRow row = toRow(line);
            if (isTransactionLine(line) || current == null) {
                rows.add(row);
                current = row;
            } else {
                current.mergeWith(row);
            }
        }
        return rows;
    }

    /** Lines selected as transaction rows: leading date token plus at least one amount token. */
    public static boolean isTransactionLine(NativeTextLine line) {
        if (line == null || line.isEmpty()) {
            return false;
        }
        List<Word> ordered = line.orderedWords();
        if (!NativeStatementPatterns.isDateToken(ordered.get(0).getContent())) {
            return false;
        }
        for (int index = 1; index < ordered.size(); index++) {
            if (NativeStatementPatterns.isAmountToken(ordered.get(index).getContent())) {
                return true;
            }
        }
        return false;
    }

    private static int findHeaderLineIndex(List<NativeTextLine> lines) {
        int limit = Math.min(HEADER_LOOKAHEAD, lines.size());
        for (int index = 0; index < limit; index++) {
            if (NativeStatementPatterns.headerKeywordCount(lines.get(index).text()) >= MIN_HEADER_KEYWORDS
                    && !isTransactionLine(lines.get(index))) {
                return index;
            }
        }
        return -1;
    }

    private static int findHeaderLineIndexAbove(List<NativeTextLine> lines, int anchorIndex) {
        int from = Math.max(0, anchorIndex - HEADER_LOOKAHEAD);
        for (int index = anchorIndex - 1; index >= from; index--) {
            if (NativeStatementPatterns.headerKeywordCount(lines.get(index).text()) >= MIN_HEADER_KEYWORDS
                    && !isTransactionLine(lines.get(index))) {
                return index;
            }
        }
        return -1;
    }

    private static boolean hasContentIn(NativeTextLine line, float left, float right) {
        for (Word word : line.orderedWords()) {
            float centerX = NativeGeometryMath.centerX(word);
            if (centerX >= left && centerX < right) {
                String content = word.getContent();
                if (content != null && !content.isBlank()) {
                    return true;
                }
            }
        }
        return false;
    }

    private static NativeTableRow toRow(NativeTextLine line) {
        NativeTableRow row = new NativeTableRow(line.getTop(), line.getBottom());
        row.addWords(line.orderedWords());
        return row;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.geometry.NativePageGeometry;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.LinkedList;
import java.util.List;

/**
 * Native layout for statements without any usable vector geometry (no grid, no boxes).
 *
 * <p>The transaction rows are selected from the text lines of the page - a row is anchored on a
 * leading date token followed by at least one monetary amount - and the columns are recovered from the
 * horizontal alignment of the selected rows only, which keeps the free flowing header/footer text of
 * the statement out of the column projection.</p>
 */
@Component
@Slf4j
public class TextAlignedRowSelectedTableLayoutBuilder implements NativeTableLayoutBuilder {

    /** Minimum number of columns for a candidate transaction table. */
    private static final int MIN_COLUMNS = 3;

    /** Minimum number of selected transaction rows required on a page. */
    private static final int MIN_SELECTED_ROWS = 2;

    @Override
    public NativeTableLayout layout() {
        return NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED;
    }

    @Override
    public List<Table> buildTables(NativePageGeometry geometry) {
        List<Table> tables = new LinkedList<>();
        if (geometry == null || !geometry.hasWords()) {
            return tables;
        }

        List<NativeTextLine> lines = NativeTextLineAssembler.assemble(geometry.getWords());
        if (lines.size() < MIN_SELECTED_ROWS) {
            return tables;
        }

        List<NativeTextLine> selectedLines = new LinkedList<>();
        for (NativeTextLine line : lines) {
            if (NativeRowSelector.isTransactionLine(line)) {
                selectedLines.add(line);
            }
        }
        if (selectedLines.size() < MIN_SELECTED_ROWS) {
            return tables;
        }

        List<List<Word>> projection = new LinkedList<>();
        for (NativeTextLine line : selectedLines) {
            projection.add(line.orderedWords());
        }
        List<Float> columnBoundaries = NativeColumnBoundaryDetector.detect(projection);
        if (columnBoundaries.size() < MIN_COLUMNS + 1) {
            return tables;
        }

        List<NativeTableRow> rows = NativeRowSelector.selectDateAnchoredRows(lines);
        if (rows.size() < MIN_SELECTED_ROWS) {
            return tables;
        }

        Table table = NativeTableAssembler.assemble(geometry.getPageNumber(), columnBoundaries, rows);
        if (table != null) {
            tables.add(table);
        }
        return tables;
    }
}

