package com.finboost.bank.statement.parser.config.document.extraction;

import lombok.Data;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Configuration;

/**
 * Configuration of the offline native transaction table extraction path.
 *
 * <p>The native path is tried first for the supported bank format families; the remote ML extraction
 * stays the default for everything else and is also used as a fallback whenever the native layouts do
 * not produce a usable transaction table.</p>
 */
@Configuration
@Data
public class NativeTableExtractionConfig {

    /** Globally enables / disables the native transaction table path. */
    @Value("${document.extraction.native.enabled:true}")
    private boolean enabled = true;

    /** Maximum number of pages read natively, {@code 0} reads the whole statement. */
    @Value("${document.extraction.native.maxPages:0}")
    private int maxPages = 0;

    /** Minimum number of date anchored rows a native result must contain to be accepted. */
    @Value("${document.extraction.native.minTransactionRows:3}")
    private int minTransactionRows = 3;
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import lombok.Data;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Native extraction policy of one bank format family: the ordered list of native layouts that are
 * tried for the statements of that family.
 */
@Data
public class NativeLayoutPolicy {

    private final String bankFormatFamily;
    private final List<NativeTableLayout> layouts;

    public NativeLayoutPolicy(String bankFormatFamily, NativeTableLayout... layouts) {
        this.bankFormatFamily = bankFormatFamily;
        this.layouts = layouts == null ? new ArrayList<>() : new ArrayList<>(Arrays.asList(layouts));
    }

    /** The layout that is tried first for this bank format family. */
    public NativeTableLayout primaryLayout() {
        return layouts.isEmpty() ? null : layouts.get(0);
    }

    public boolean supports(NativeTableLayout layout) {
        return layouts.contains(layout);
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import org.springframework.stereotype.Component;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

import static com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout.BORDERED_GRID;
import static com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout.BOX_GUIDED;
import static com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED;

/**
 * Registry of the native layout policies of the supported bank format families.
 *
 * <p>The families and the layout order come from the statement fixture corpus of the repository
 * ({@code src/test/resources/pdf-samples-latest}):</p>
 * <ul>
 *     <li>families whose formats draw a complete ruling grid start with {@link NativeTableLayout#BORDERED_GRID}
 *     (PNB, Bank of Baroda, Bandhan, IDBI, IDFC, Standard Chartered, Suryoday, TJSB, Mahanagar
 *     Co-op, Federal, IndusInd, RBL, Central Bank, Union Bank, Axis, SBI);</li>
 *     <li>families whose formats draw shaded bands or filled cell rectangles instead of a grid start with
 *     {@link NativeTableLayout#BOX_GUIDED} (HDFC, ICICI, Indian Bank, Kotak, Yes, Ahmednagar, Citi,
 *     Deutsche, Indian Overseas);</li>
 *     <li>every supported family finally falls back to {@link NativeTableLayout#TEXT_ALIGNED_ROW_SELECTED}
 *     because most families contain at least one format without usable vector geometry.</li>
 * </ul>
 *
 * <p>Bank codes that are not registered here are extracted with the remote ML engine, which stays the
 * default for unknown or unsupported layouts.</p>
 */
@Component
public class NativeLayoutPolicyRegistry {

    private final Map<String, NativeLayoutPolicy> policiesByFamily = new LinkedHashMap<>();
    private final Map<String, String> familyAliases = new LinkedHashMap<>();

    public NativeLayoutPolicyRegistry() {
        // ---- bordered grid first families -------------------------------------------------------
        registerBorderedGridFamily("PNB");
        registerBorderedGridFamily("BANK_OF_BARODA");
        registerBorderedGridFamily("BANDHAN");
        registerBorderedGridFamily("IDBI");
        registerBorderedGridFamily("IDFC");
        registerBorderedGridFamily("STANDARD_CHARTERED");
        registerBorderedGridFamily("SURYODAY_SMALL_FINANCE_BANK_LTD");
        registerBorderedGridFamily("TJSB_BANK");
        registerBorderedGridFamily("GS_MAHANAGAR_CO_OP_BANK");
        registerBorderedGridFamily("FEDERAL");
        registerBorderedGridFamily("INDUSIND");
        registerBorderedGridFamily("RBL");
        registerBorderedGridFamily("CENTRAL_BANK");
        registerBorderedGridFamily("UNION_BANK");
        registerBorderedGridFamily("AXIS");
        registerBorderedGridFamily("SBI");

        // ---- box guided first families ----------------------------------------------------------
        registerBoxGuidedFamily("HDFC");
        registerBoxGuidedFamily("ICICI");
        registerBoxGuidedFamily("INDIAN_BANK");
        registerBoxGuidedFamily("KOTAK");
        registerBoxGuidedFamily("YES");
        registerBoxGuidedFamily("AHMEDNAGAR");
        registerBoxGuidedFamily("CITI");
        registerBoxGuidedFamily("DEUTSCHE");
        registerBoxGuidedFamily("INDIAN_OVERSEAS");

        // ---- aliases used by the fixture corpus / older bank code spellings ---------------------
        registerAlias("BOB", "BANK_OF_BARODA");
        registerAlias("BARODA", "BANK_OF_BARODA");
        registerAlias("UNION", "UNION_BANK");
        registerAlias("CBI", "CENTRAL_BANK");
        registerAlias("CENTRAL", "CENTRAL_BANK");
        registerAlias("INDIAN", "INDIAN_BANK");
        registerAlias("IOB", "INDIAN_OVERSEAS");
        registerAlias("INDIAN_OVERSEAS_BANK", "INDIAN_OVERSEAS");
        registerAlias("DEUSTCHE", "DEUTSCHE");
        registerAlias("DEUTSCHE_BANK", "DEUTSCHE");
        registerAlias("GS_MAHANAGAR_CO_OP_BANK_LTD", "GS_MAHANAGAR_CO_OP_BANK");
        registerAlias("MAHANAGAR", "GS_MAHANAGAR_CO_OP_BANK");
        registerAlias("TJSB", "TJSB_BANK");
        registerAlias("SURYODAY", "SURYODAY_SMALL_FINANCE_BANK_LTD");
        registerAlias("SURYODAY_SMALL_FINANCE_BANK", "SURYODAY_SMALL_FINANCE_BANK_LTD");
        registerAlias("BANDHAN_BANK", "BANDHAN");
        registerAlias("YES_BANK", "YES");
        registerAlias("KOTAK_BANK", "KOTAK");
        registerAlias("AXIS_BANK", "AXIS");
        registerAlias("PUNJAB_NATIONAL_BANK", "PNB");
        registerAlias("STATE_BANK_OF_INDIA", "SBI");
    }

    private void registerBorderedGridFamily(String family) {
        policiesByFamily.put(family,
                new NativeLayoutPolicy(family, BORDERED_GRID, BOX_GUIDED, TEXT_ALIGNED_ROW_SELECTED));
    }

    private void registerBoxGuidedFamily(String family) {
        policiesByFamily.put(family,
                new NativeLayoutPolicy(family, BOX_GUIDED, BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED));
    }

    private void registerAlias(String alias, String family) {
        familyAliases.put(alias, family);
    }

    /**
     * Resolves the native policy of a bank code.
     *
     * @param bankCode the bank code of the statement, may be {@code null}
     * @return the policy, or {@link Optional#empty()} when the family has no supported native layout
     */
    public Optional<NativeLayoutPolicy> policyFor(String bankCode) {
        String family = resolveFamily(bankCode);
        if (family == null) {
            return Optional.empty();
        }
        return Optional.ofNullable(policiesByFamily.get(family));
    }

    public boolean isSupported(String bankCode) {
        return policyFor(bankCode).isPresent();
    }

    /** Canonical family name of a bank code, {@code null} when the bank code is blank. */
    public String resolveFamily(String bankCode) {
        String normalized = normalize(bankCode);
        if (normalized == null) {
            return null;
        }
        if (policiesByFamily.containsKey(normalized)) {
            return normalized;
        }
        return familyAliases.get(normalized);
    }

    /** All natively supported bank format families. */
    public Set<String> supportedFamilies() {
        return Collections.unmodifiableSet(policiesByFamily.keySet());
    }

    private String normalize(String bankCode) {
        if (bankCode == null || bankCode.isBlank()) {
            return null;
        }
        return bankCode.trim().toUpperCase()
                .replace('-', '_')
                .replace(' ', '_')
                .replace('.', '_');
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeExtractionDiagnostics;
import lombok.Data;

/**
 * Result of one native transaction table extraction attempt for a statement.
 */
@Data
public class NativeExtractionAttempt {

    /** The accepted native result, {@code null} when no native layout produced a usable table. */
    private final DocumentExtractionResult result;

    /** Diagnostics of the attempt, never {@code null}. */
    private final NativeExtractionDiagnostics diagnostics;

    public NativeExtractionAttempt(DocumentExtractionResult result, NativeExtractionDiagnostics diagnostics) {
        this.result = result;
        this.diagnostics = diagnostics == null ? new NativeExtractionDiagnostics() : diagnostics;
    }

    public static NativeExtractionAttempt notAttempted(String bankFormatFamily, String reason) {
        return new NativeExtractionAttempt(null, NativeExtractionDiagnostics.notAttempted(bankFormatFamily, reason));
    }

    public boolean isSuccessful() {
        return result != null;
    }

    /** {@code true} when a native policy existed and the native layouts were executed. */
    public boolean wasAttempted() {
        return diagnostics.isAttempted();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.Page;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Assigns the page/word indices of a natively built document exactly the same way the remote ML
 * response mapper does, so that {@link TableCell#getContent()} orders the words identically for both
 * extraction engines.
 */
public final class NativeWordIndexer {

    private NativeWordIndexer() {
    }

    public static void assignWordIndices(DocumentExtractionResult result) {
        if (result == null || result.getPages() == null) {
            return;
        }

        int currentWordIndex = 1;

        List<Integer> pageNumbers = new ArrayList<>(result.getPages().keySet());
        Collections.sort(pageNumbers);

        for (Integer pageNumber : pageNumbers) {
            Page page = result.getPages().get(pageNumber);
            if (page == null || page.getTables() == null) {
                continue;
            }

            List<Integer> tableIndices = new ArrayList<>(page.getTables().keySet());
            Collections.sort(tableIndices);

            for (Integer tableIndex : tableIndices) {
                Table table = page.getTables().get(tableIndex);
                if (table == null || table.getCells() == null) {
                    continue;
                }

                List<Integer> rowIndices = new ArrayList<>(table.getCells().keySet());
                Collections.sort(rowIndices);

                for (Integer rowIndex : rowIndices) {
                    Map<Integer, TableCell> row = table.getCells().get(rowIndex);
                    if (row == null) {
                        continue;
                    }

                    List<Integer> cellIndices = new ArrayList<>(row.keySet());
                    Collections.sort(cellIndices);

                    for (Integer cellIndex : cellIndices) {
                        TableCell cell = row.get(cellIndex);
                        if (cell == null || cell.getWords() == null) {
                            continue;
                        }
                        for (Word word : cell.getWords()) {
                            word.setPageIndex(pageNumber);
                            word.setWordIndex(currentWordIndex++);
                        }
                    }
                }
            }
        }
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.config.document.extraction.NativeTableExtractionConfig;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeExtractionDiagnostics;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Page;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TransactionExtractionMode;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.geometry.NativePageGeometry;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.geometry.NativePdfGeometryExtractor;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout.NativeTableAssembler;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout.NativeTableLayoutBuilder;
import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.io.File;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.function.Predicate;

/**
 * Offline transaction table extraction: rebuilds the transaction grid of an electronic bank statement
 * from the PDF itself, without invoking the remote ML document extraction service.
 *
 * <p>The native layouts of the statement's bank format family are tried in policy order
 * ({@link NativeLayoutPolicyRegistry}). Every candidate is handed to the caller supplied acceptor,
 * which runs the regular downstream document analysis; the first candidate that yields a usable
 * transaction table wins. When no candidate is accepted the caller falls back to the remote ML
 * engine.</p>
 */
@Service
@Slf4j
public class NativeTransactionTableExtractionService {

    static final String REASON_DISABLED = "NATIVE_EXTRACTION_DISABLED";
    static final String REASON_NO_POLICY = "NO_NATIVE_POLICY_FOR_BANK_FORMAT_FAMILY";
    static final String REASON_NO_FILE = "STATEMENT_FILE_UNAVAILABLE";
    static final String REASON_NO_GEOMETRY = "NO_NATIVE_PAGE_GEOMETRY";
    static final String REASON_NO_TEXT_LAYER = "NO_TEXT_LAYER_IN_PDF";
    static final String REASON_NO_LAYOUT_MATCH = "NO_NATIVE_LAYOUT_PRODUCED_TRANSACTION_TABLE";
    static final String REASON_ERROR = "NATIVE_EXTRACTION_ERROR";

    private final NativeTableExtractionConfig config;
    private final NativeLayoutPolicyRegistry policyRegistry;
    private final NativePdfGeometryExtractor geometryExtractor;
    private final Map<NativeTableLayout, NativeTableLayoutBuilder> builders = new EnumMap<>(NativeTableLayout.class);

    @Autowired
    public NativeTransactionTableExtractionService(NativeTableExtractionConfig config,
                                                  NativeLayoutPolicyRegistry policyRegistry,
                                                  NativePdfGeometryExtractor geometryExtractor,
                                                  List<NativeTableLayoutBuilder> layoutBuilders) {
        this.config = config;
        this.policyRegistry = policyRegistry;
        this.geometryExtractor = geometryExtractor;
        if (layoutBuilders != null) {
            for (NativeTableLayoutBuilder builder : layoutBuilders) {
                this.builders.put(builder.layout(), builder);
            }
        }
    }

    /** {@code true} when the bank format family of the request has a native layout policy. */
    public boolean isNativelySupported(String bankCode) {
        return config.isEnabled() && policyRegistry.isSupported(bankCode);
    }

    public NativeLayoutPolicyRegistry getPolicyRegistry() {
        return policyRegistry;
    }

    /**
     * Tries to extract the transaction tables of the request natively.
     *
     * @param request  the extraction request, the statement file must be an electronic PDF
     * @param acceptor runs the downstream document analysis on a native candidate and reports whether
     *                 the candidate carries a usable transaction table
     */
    public NativeExtractionAttempt extract(DocumentExtractionRequest request,
                                           Predicate<DocumentExtractionResult> acceptor) {
        String bankCode = request == null ? null : request.getBankName();
        String family = policyRegistry.resolveFamily(bankCode);

        if (!config.isEnabled()) {
            return NativeExtractionAttempt.notAttempted(family, REASON_DISABLED);
        }

        Optional<NativeLayoutPolicy> policyHolder = policyRegistry.policyFor(bankCode);
        if (policyHolder.isEmpty()) {
            return NativeExtractionAttempt.notAttempted(family, REASON_NO_POLICY);
        }
        NativeLayoutPolicy policy = policyHolder.get();

        File statementFile = request.getStatementFile();
        if (statementFile == null || !statementFile.isFile() || !statementFile.canRead()) {
            return NativeExtractionAttempt.notAttempted(family, REASON_NO_FILE);
        }

        NativeExtractionDiagnostics diagnostics = new NativeExtractionDiagnostics();
        diagnostics.setBankFormatFamily(policy.getBankFormatFamily());
        diagnostics.setAttempted(true);

        try (PDDocument document = Loader.loadPDF(statementFile)) {
            List<NativePageGeometry> geometries = geometryExtractor.extract(document, config.getMaxPages());
            if (geometries.isEmpty()) {
                diagnostics.setSkipOrFailureReason(REASON_NO_GEOMETRY);
                return new NativeExtractionAttempt(null, diagnostics);
            }
            if (!hasTextLayer(geometries)) {
                diagnostics.setSkipOrFailureReason(REASON_NO_TEXT_LAYER);
                return new NativeExtractionAttempt(null, diagnostics);
            }

            for (NativeTableLayout layout : policy.getLayouts()) {
                NativeTableLayoutBuilder builder = builders.get(layout);
                if (builder == null) {
                    continue;
                }
                diagnostics.addAttemptedLayout(layout);

                DocumentExtractionResult candidate = buildCandidate(geometries, builder, layout);
                if (candidate == null) {
                    continue;
                }
                if (acceptor != null && !acceptor.test(candidate)) {
                    log.debug("Native layout {} rejected for bank format family {}", layout,
                            policy.getBankFormatFamily());
                    continue;
                }

                diagnostics.setSucceeded(true);
                diagnostics.setSelectedLayout(layout);
                diagnostics.setNativeTableCount(countTables(candidate));
                diagnostics.setNativeRowCount(countTransactionRows(candidate));
                candidate.setNativeExtractionDiagnostics(diagnostics);
                candidate.setExtractionMode(TransactionExtractionMode.NATIVE);
                candidate.setNativeTableLayout(layout);
                log.info("Native transaction table extraction succeeded for bank format family {} using layout {}",
                        policy.getBankFormatFamily(), layout);
                return new NativeExtractionAttempt(candidate, diagnostics);
            }

            diagnostics.setSkipOrFailureReason(REASON_NO_LAYOUT_MATCH);
            return new NativeExtractionAttempt(null, diagnostics);
        } catch (Exception e) {
            log.warn("Native transaction table extraction failed for bank format family {}: {}",
                    diagnostics.getBankFormatFamily(), e.getMessage());
            diagnostics.setSkipOrFailureReason(REASON_ERROR + ": " + e.getMessage());
            return new NativeExtractionAttempt(null, diagnostics);
        }
    }

    /**
     * Builds a full {@link DocumentExtractionResult} for one native layout. Returns {@code null} when
     * the layout does not detect enough transaction rows in the whole document.
     */
    private DocumentExtractionResult buildCandidate(List<NativePageGeometry> geometries,
                                                    NativeTableLayoutBuilder builder,
                                                    NativeTableLayout layout) {
        Map<Integer, Page> pages = new LinkedHashMap<>();
        int dateAnchoredRows = 0;

        for (NativePageGeometry geometry : geometries) {
            Page page = new Page();
            page.setPageNumber(geometry.getPageNumber());
            page.setWidth((double) geometry.getWidth());
            page.setHeight((double) geometry.getHeight());
            page.setContent(geometry.getTextContent());
            page.setWords(new ArrayList<>(geometry.getWords()));

            Map<Integer, Table> tables = new LinkedHashMap<>();
            List<Table> pageTables;
            try {
                pageTables = builder.buildTables(geometry);
            } catch (Exception e) {
                log.debug("Native layout {} failed on page {}: {}", layout, geometry.getPageNumber(), e.getMessage());
                pageTables = new LinkedList<>();
            }
            int tableIndex = 0;
            for (Table table : pageTables) {
                if (table == null) {
                    continue;
                }
                dateAnchoredRows += NativeTableAssembler.countDateAnchoredRows(table);
                tables.put(tableIndex++, table);
            }
            page.setTables(tables);
            pages.put(page.getPageNumber(), page);
        }

        if (dateAnchoredRows < Math.max(1, config.getMinTransactionRows())) {
            return null;
        }

        DocumentExtractionResult candidate = new DocumentExtractionResult();
        candidate.setPages(pages);
        candidate.setNoOfPages(pages.size());
        candidate.setExtractionMode(TransactionExtractionMode.NATIVE);
        candidate.setNativeTableLayout(layout);
        NativeWordIndexer.assignWordIndices(candidate);
        return candidate;
    }

    private boolean hasTextLayer(List<NativePageGeometry> geometries) {
        for (NativePageGeometry geometry : geometries) {
            if (geometry.hasWords()) {
                return true;
            }
        }
        return false;
    }

    private int countTables(DocumentExtractionResult result) {
        int count = 0;
        for (Page page : result.getPages().values()) {
            if (page.getTables() != null) {
                count += page.getTables().size();
            }
        }
        return count;
    }

    private int countTransactionRows(DocumentExtractionResult result) {
        int count = 0;
        for (Page page : result.getPages().values()) {
            if (page.getTables() == null) {
                continue;
            }
            for (Table table : page.getTables().values()) {
                if (table != null && table.isBankTransactions()) {
                    count += table.getCells() == null ? 0 : table.getCells().size();
                }
            }
        }
        if (count == 0) {
            for (Page page : result.getPages().values()) {
                if (page.getTables() == null) {
                    continue;
                }
                for (Table table : page.getTables().values()) {
                    count += NativeTableAssembler.countDateAnchoredRows(table);
                }
            }
        }
        return count;
    }

    /** Unused words guard kept for readability of the geometry contract. */
    @SuppressWarnings("unused")
    private static boolean hasContent(List<Word> words) {
        return words != null && !words.isEmpty();
    }
}

