    private static boolean checkIfDatesShouldBeSwapped(List<BankTransactionVO> transactions, boolean isReversedOrder) {
        if (transactions.size() < 2) {
            return false;
        }


        // Check each transaction's dates
        for (BankTransactionVO transaction : transactions) {
            Date transactionDate = transaction.getTransactionDate();
            Date valueDate = transaction.getTransactionValueDate();

            if (transactionDate == null || valueDate == null) {
                continue;
            }

            // Skip if dates are equal
            if (transactionDate.equals(valueDate)) {
                continue;
            }

            // If transaction date is before value date, our column assignment is wrong
            if (transactionDate.before(valueDate)) {
                log.debug("Found transaction date {} before value date {} - need to swap", 
                    transactionDate, valueDate);
                return true;
            }
        }

        // If all dates were equal, no need to swap
        return false;
    }

    private static void swapDatesInTransactions(List<BankTransactionVO> transactions) {
        for (BankTransactionVO transaction : transactions) {
            Date tempDate = transaction.getTransactionDate();
            transaction.setTransactionDate(transaction.getTransactionValueDate());
            transaction.setTransactionValueDate(tempDate);
        }
    }

    private static boolean hasValueDates(List<BankTransactionVO> transactions) {
        // Check first few transactions to see if value dates exist
        int samplesToCheck = Math.min(transactions.size(), 5);
        int valueDatesFound = 0;

        for (int i = 0; i < samplesToCheck; i++) {
            if (transactions.get(i).getTransactionValueDate() != null) {
                valueDatesFound++;
            }
        }

        // Consider value dates exist if found in majority of samples
        return valueDatesFound > (samplesToCheck / 2);
    }

