 * <p>An account is reported as {@code NATIVE} only when every one of its statements was parsed by
 * the offline native path, as {@code ML} when the remote ML engine handled all of them and as
 * {@code NATIVE_FALLBACK_ML} as soon as one statement had to fall back to the ML engine.</p>
 */
static void applyExtractionModeToAccount(AccountVO accountVO, List<BankStatementVO> statements) {
    if (accountVO == null || statements == null || statements.isEmpty()) {
        return;
    }
    TransactionExtractionMode mode = null;
    List<NativeTableLayout> layouts = new ArrayList<>();
    for (BankStatementVO statement : statements) {
        if (statement == null) {
            continue;
        }
        TransactionExtractionMode statementMode = statement.getTransactionExtractionMode();
        if (statementMode == null) {
            statementMode = TransactionExtractionMode.ML;
        }
        mode = TransactionExtractionMode.merge(mode, statementMode);
        NativeTableLayout layout = statement.getNativeTableLayout();
        if (layout != null && !layouts.contains(layout)) {
            layouts.add(layout);
        }
    }
    accountVO.setTransactionExtractionMode(mode);
    accountVO.setNativeTableLayouts(layouts);
}

