public static boolean isAmountToken(String token) {
    if (token == null) {
        return false;
    }
    String trimmed = token.trim();
    if (trimmed.isEmpty()) {
        return false;
    }
    if (!trimmed.matches(".*\\d.*")) {
        return false;
    }
    return AMOUNT_TOKEN.matcher(trimmed).matches();
}

/**
 * {@code true} when the cell content carries a date. Statements frequently wrap a single date over
 * two visual lines ({@code "13/01"} + {@code "/2025"}), therefore the whitespace collapsed content
 * and the individual tokens are checked as well.
 */
public static boolean containsDateToken(String content) {
    if (content == null || content.isBlank()) {
        return false;
    }
    String trimmed = content.trim();
    if (isDateToken(trimmed)) {
        return true;
    }
    if (isDateToken(trimmed.replaceAll("\\s+", ""))) {
        return true;
    }
    for (String token : trimmed.split("\\s+")) {
        if (isDateToken(token)) {
            return true;
        }
    }
    return false;
}

