/** Two rulings closer than this are the same grid line. */
private static final float POSITION_TOLERANCE = 0.02f;

/** Minimum width of a grid column in inches. */
private static final float MIN_COLUMN_WIDTH = 0.07f;

/** Minimum height of a grid row in inches. */
private static final float MIN_ROW_HEIGHT = 0.045f;

/** A vertical ruling must cover at least this fraction of the grid height to be a column line. */
private static final float MIN_COLUMN_COVERAGE = 0.45f;

/** A vertical ruling must cover at least this fraction of a row to close a cell. */
private static final float MIN_CELL_COVERAGE = 0.55f;

/** A horizontal ruling must cover at least this fraction of the grid width to be a row line. */
private static final float MIN_ROW_LINE_COVERAGE = 0.30f;

/** Minimum number of columns for a candidate transaction grid. */
private static final int MIN_COLUMNS = 3;

@Override
public NativeTableLayout layout() {
    return NativeTableLayout.BORDERED_GRID;
}

@Override
public List<Table> buildTables(NativePageGeometry geometry) {
    List<Table> tables = new LinkedList<>();
    if (geometry == null || !geometry.hasWords() || !geometry.hasRulingGrid()) {
        return tables;
    }

    List<NativeRuling> horizontal = sortedByPosition(geometry.getHorizontalRulings());
    List<NativeRuling> vertical = sortedByExtentStart(geometry.getVerticalRulings());
    if (horizontal.size() < 2 || vertical.size() < 2) {
        return tables;
    }

    // Grid candidates are discovered from the vertical rulings: every set of vertical rulings whose
    // vertical extents chain together bounds one grid. This is independent of the page scale, which
    // matters because statements are rendered on very different page sizes.
    for (List<NativeRuling> gridColumns : groupByVerticalExtent(vertical)) {
        Table table = buildGridTable(geometry, gridColumns, horizontal);
        if (table != null) {
            tables.add(table);
        }
    }
    return tables;
}

private Table buildGridTable(NativePageGeometry geometry, List<NativeRuling> gridColumns,
                             List<NativeRuling> horizontal) {
    if (gridColumns.size() < MIN_COLUMNS + 1) {
        return null;
    }

    float gridTop = Float.MAX_VALUE;
    float gridBottom = -Float.MAX_VALUE;
    for (NativeRuling ruling : gridColumns) {
        gridTop = Math.min(gridTop, ruling.getStart());
        gridBottom = Math.max(gridBottom, ruling.getEnd());
    }
    if (gridBottom - gridTop <= MIN_ROW_HEIGHT) {
        return null;
    }

    List<NativeRuling> columnRulings = new LinkedList<>();
    for (NativeRuling ruling : gridColumns) {
        if (ruling.covers(gridTop, gridBottom, MIN_COLUMN_COVERAGE)) {
            columnRulings.add(ruling);
        }
    }
    if (columnRulings.isEmpty()) {
        columnRulings = new LinkedList<>(gridColumns);
    }
    List<Float> columnBoundaries = boundariesOf(columnRulings);
    if (columnBoundaries.size() < MIN_COLUMNS + 1) {
        return null;
    }

    float left = columnBoundaries.get(0);
    float right = columnBoundaries.get(columnBoundaries.size() - 1);
    List<Float> rowBoundaries = rowBoundariesOf(horizontal, gridTop, gridBottom, left, right);
    if (rowBoundaries.size() < 2) {
        return null;
    }

    List<Word> gridWords = wordsWithin(geometry.getWords(), left, gridTop, right, gridBottom);
    if (gridWords.isEmpty()) {
        return null;
    }

    Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();
    int rowIndex = 0;
    float tableTop = Float.MAX_VALUE;
    float tableBottom = -Float.MAX_VALUE;
    for (int band = 0; band < rowBoundaries.size() - 1; band++) {
        float rowTop = rowBoundaries.get(band);
        float rowBottom = rowBoundaries.get(band + 1);
        Map<Integer, TableCell> rowCells = buildRowCells(rowIndex, rowTop, rowBottom, columnBoundaries,
                columnRulings, gridWords);
        if (rowCells.isEmpty() || isBlankRow(rowCells)) {
            continue;
        }
        cells.put(rowIndex, rowCells);
        tableTop = Math.min(tableTop, rowTop);
        tableBottom = Math.max(tableBottom, rowBottom);
        rowIndex++;
    }
    if (cells.isEmpty()) {
        return null;
    }

    Table table = new Table();
    table.setPageNumber(geometry.getPageNumber());
    table.setX1(left);
    table.setY1(tableTop);
    table.setX2(right);
    table.setY2(tableTop);
    table.setX3(right);
    table.setY3(tableBottom);
    table.setX4(left);
    table.setY4(tableBottom);
    table.setCells(cells);
    table.setTotalRows(cells.size());
    table.setTotalColumns(columnBoundaries.size() - 1);
    table.setColType(new ArrayList<>());
    table.setTxnColType(new ArrayList<>());
    table.setSpanOffset(0);
    table.setSpanLength(0);
    table.setColumnBoundaries(new ArrayList<>(columnBoundaries));
    return table;
}

/**
 * Row boundaries of a grid: the horizontal rulings inside the grid extent that span a relevant part
 * of the grid width, plus the grid top and bottom.
 */
private List<Float> rowBoundariesOf(List<NativeRuling> horizontal, float gridTop, float gridBottom,
                                    float left, float right) {
    List<Float> positions = new LinkedList<>();
    positions.add(gridTop);
    for (NativeRuling ruling : horizontal) {
        if (ruling.getPosition() < gridTop - POSITION_TOLERANCE
                || ruling.getPosition() > gridBottom + POSITION_TOLERANCE) {
            continue;
        }
        if (!ruling.covers(left, right, MIN_ROW_LINE_COVERAGE)) {
            continue;
        }
        positions.add(ruling.getPosition());
    }
    positions.add(gridBottom);

    List<Float> boundaries = new LinkedList<>();
    for (Float position : positions) {
        if (boundaries.isEmpty() || position - boundaries.get(boundaries.size() - 1) > MIN_ROW_HEIGHT) {
