private Table buildGridTable(NativePageGeometry geometry, List<NativeRuling> gridRows, List<NativeRuling> vertical) {
    if (gridRows.size() < 2) {
        return null;
    }
    float gridTop = gridRows.get(0).getPosition();
    float gridBottom = gridRows.get(gridRows.size() - 1).getPosition();
    float gridHeight = gridBottom - gridTop;
    if (gridHeight <= MIN_ROW_HEIGHT) {
        return null;
    }

    List<NativeRuling> columnRulings = new LinkedList<>();
    for (NativeRuling ruling : vertical) {
        if (ruling.covers(gridTop, gridBottom, MIN_COLUMN_COVERAGE)) {
            columnRulings.add(ruling);
        }
    }
    List<Float> columnBoundaries = boundariesOf(columnRulings);
    if (columnBoundaries.size() < MIN_COLUMNS + 1) {
        return null;
    }

    List<Float> rowBoundaries = new LinkedList<>();
    for (NativeRuling ruling : gridRows) {
        if (rowBoundaries.isEmpty()
                || ruling.getPosition() - rowBoundaries.get(rowBoundaries.size() - 1) > MIN_ROW_HEIGHT) {
            rowBoundaries.add(ruling.getPosition());
        }
    }
    if (rowBoundaries.size() < 2) {
        return null;
    }

    float left = columnBoundaries.get(0);
    float right = columnBoundaries.get(columnBoundaries.size() - 1);
    List<Word> gridWords = wordsWithin(geometry.getWords(), left, gridTop, right, gridBottom);
    if (gridWords.isEmpty()) {
        return null;
    }

    Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();
    int rowIndex = 0;
    float tableTop = Float.MAX_VALUE;
    float tableBottom = -Float.MAX_VALUE;
    for (int band = 0; band < rowBoundaries.size() - 1; band++) {
        float rowTop = rowBoundaries.get(band);
        float rowBottom = rowBoundaries.get(band + 1);
        Map<Integer, TableCell> rowCells = buildRowCells(rowIndex, rowTop, rowBottom, columnBoundaries,
                columnRulings, gridWords);
        if (rowCells.isEmpty() || isBlankRow(rowCells)) {
            continue;
        }
        cells.put(rowIndex, rowCells);
        tableTop = Math.min(tableTop, rowTop);
        tableBottom = Math.max(tableBottom, rowBottom);
        rowIndex++;
    }
    if (cells.isEmpty()) {
        return null;
    }

    Table table = new Table();
    table.setPageNumber(geometry.getPageNumber());
    table.setX1(left);
    table.setY1(tableTop);
    table.setX2(right);
    table.setY2(tableTop);
    table.setX3(right);
    table.setY3(tableBottom);
    table.setX4(left);
    table.setY4(tableBottom);
    table.setCells(cells);
    table.setTotalRows(cells.size());
    table.setTotalColumns(columnBoundaries.size() - 1);
    table.setColType(new ArrayList<>());
    table.setTxnColType(new ArrayList<>());
    table.setSpanOffset(0);
    table.setSpanLength(0);
    table.setColumnBoundaries(new ArrayList<>(columnBoundaries));
    return table;
}

