    private List<NativeRuling> sortedByExtentStart(List<NativeRuling> rulings) {
        List<NativeRuling> sorted = new ArrayList<>(rulings == null ? new LinkedList<>() : rulings);
        sorted.sort(Comparator.comparing(NativeRuling::getStart).thenComparing(NativeRuling::getPosition));
        return sorted;
    }

    /**
     * Splits the vertical rulings of a page into grid candidates by chaining their vertical extents.
     * Rulings whose extents overlap (or touch) belong to the same grid, a real vertical gap starts a new
     * grid. Working on the extents instead of on an absolute distance keeps the detection independent of
     * the page size and of the row height of the statement format.
     */
    private List<List<NativeRuling>> groupByVerticalExtent(List<NativeRuling> vertical) {
        List<List<NativeRuling>> groups = new LinkedList<>();
        List<NativeRuling> current = new LinkedList<>();
        float currentBottom = -Float.MAX_VALUE;
        for (NativeRuling ruling : vertical) {
            if (current.isEmpty()) {
                current.add(ruling);
                currentBottom = ruling.getEnd();
                continue;
            }
            if (ruling.getStart() <= currentBottom + MIN_ROW_HEIGHT) {
                current.add(ruling);
                currentBottom = Math.max(currentBottom, ruling.getEnd());
            } else {
                groups.add(current);
                current = new LinkedList<>();
                current.add(ruling);
                currentBottom = ruling.getEnd();
            }
        }
        if (!current.isEmpty()) {
            groups.add(current);
        }
        return groups;
    }
}

