public final class NativeStatementPatterns {

    /** Month name prefixes accepted inside a date token. */
    private static final String MONTH = "(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)";

/** A box narrower than this is a bullet / underline decoration, not a table guide. */
private static final float MIN_BOX_WIDTH = 0.10f;

/** A guide band must span at least this fraction of the page width. */
private static final float MIN_BAND_WIDTH_RATIO = 0.40f;

/** A guide box taller than this is a page decoration, not a row band or a header band. */
private static final float MAX_BAND_HEIGHT = 1.20f;

/** Vertical tolerance when grouping boxes into a band. */
private static final float BAND_TOLERANCE = 0.02f;

/** Tolerance used when collapsing the shared edges of neighbouring boxes into one boundary. */
private static final float EDGE_TOLERANCE = 0.03f;

/** Bottom margin kept free when a single header band has to be extended down the page. */
private static final float PAGE_BOTTOM_MARGIN = 0.35f;

/** Minimum number of columns for a candidate transaction table. */
private static final int MIN_COLUMNS = 3;

@Override
public NativeTableLayout layout() {
    return NativeTableLayout.BOX_GUIDED;
}

@Override
public List<Table> buildTables(NativePageGeometry geometry) {
    List<Table> tables = new LinkedList<>();
    if (geometry == null || !geometry.hasWords() || !geometry.hasBoxes()) {
        return tables;
    }

    List<List<NativeBox>> bands = guideBands(geometry);
    if (bands.isEmpty()) {
        return tables;
    }

    float regionLeft = Float.MAX_VALUE;
    float regionRight = -Float.MAX_VALUE;
    float regionTop = Float.MAX_VALUE;
    float regionBottom = -Float.MAX_VALUE;
    for (List<NativeBox> band : bands) {
        for (NativeBox box : band) {
            regionLeft = Math.min(regionLeft, box.getLeft());
            regionRight = Math.max(regionRight, box.getRight());
            regionTop = Math.min(regionTop, box.getTop());
            regionBottom = Math.max(regionBottom, box.getBottom());
        }
    }

    if (bands.size() < 3) {
        // a single (header) band only guides the top of the table, the rows continue below it
        regionBottom = Math.max(regionBottom, geometry.getHeight() - PAGE_BOTTOM_MARGIN);
    }

    List<NativeTextLine> lines = NativeTextLineAssembler.within(
            NativeTextLineAssembler.assemble(geometry.getWords()), regionTop, regionBottom);
    lines = restrictHorizontally(lines, regionLeft, regionRight);
    if (lines.size() < 2) {
        return tables;
    }

    List<Float> columnBoundaries = columnBoundariesFromBands(bands);
    if (columnBoundaries.size() < MIN_COLUMNS + 1) {
        List<List<Word>> rowsOfWords = new LinkedList<>();
        for (NativeTextLine line : lines) {
            rowsOfWords.add(line.orderedWords());
        }
        columnBoundaries = NativeColumnBoundaryDetector.detect(rowsOfWords);
    }
    if (columnBoundaries.size() < MIN_COLUMNS + 1) {
        return tables;
    }

    List<NativeTableRow> rows = NativeRowSelector.selectRows(lines, columnBoundaries);
    if (rows.size() < 2) {
        return tables;
    }

    Table table = NativeTableAssembler.assemble(geometry.getPageNumber(), columnBoundaries, rows);
    if (table != null) {
        tables.add(table);
    }
    return tables;
}

/**
 * Guide bands of a page: horizontal groups of boxes that together span a relevant part of the page
 * width. A band can be one wide shaded row band or a row of side by side cell rectangles.
 */
private List<List<NativeBox>> guideBands(NativePageGeometry geometry) {
    List<NativeBox> candidates = new LinkedList<>();
    for (NativeBox box : geometry.getBoxes()) {
        if (box.width() >= MIN_BOX_WIDTH && box.height() > 0.01f && box.height() <= MAX_BAND_HEIGHT) {
            candidates.add(box);
        }
    }
    candidates.sort(Comparator.comparing(NativeBox::getTop).thenComparing(NativeBox::getLeft));

    float minBandWidth = MIN_BAND_WIDTH_RATIO * Math.max(geometry.getWidth(), 0.001f);
    List<List<NativeBox>> bands = new LinkedList<>();
    for (List<NativeBox> band : groupIntoBands(candidates)) {
        float left = Float.MAX_VALUE;
        float right = -Float.MAX_VALUE;
        for (NativeBox box : band) {
            left = Math.min(left, box.getLeft());
            right = Math.max(right, box.getRight());
        }
        if (right - left >= minBandWidth) {
            bands.add(band);
        }
    }
    return bands;
}

