/**
 * Uses the band with the highest number of side by side boxes as the column guide: the shared edges
 * of its boxes are the column boundaries. Such a band is the shaded header row (one box per header
 * cell) of many statement formats.
 */
private List<Float> columnBoundariesFromBands(List<List<NativeBox>> bands) {
    List<NativeBox> guideBand = null;
    for (List<NativeBox> band : bands) {
        List<NativeBox> distinct = distinctBoxes(band);
        if (distinct.size() >= MIN_COLUMNS && (guideBand == null || distinct.size() > guideBand.size())) {
            guideBand = distinct;
        }
    }
    if (guideBand == null) {
        return new LinkedList<>();
    }
    List<Float> positions = new LinkedList<>();
    for (NativeBox box : guideBand) {
        positions.add(box.getLeft());
        positions.add(box.getRight());
    }
    return NativeColumnBoundaryDetector.fromPositions(positions, EDGE_TOLERANCE);
}

/** Removes boxes that are drawn several times at the same position. */
private List<NativeBox> distinctBoxes(List<NativeBox> band) {
    List<NativeBox> distinct = new ArrayList<>();
    List<NativeBox> ordered = new ArrayList<>(band);
    ordered.sort(Comparator.comparing(NativeBox::getLeft));
    for (NativeBox box : ordered) {
        boolean duplicate = false;
        for (NativeBox existing : distinct) {
            if (Math.abs(existing.getLeft() - box.getLeft()) <= EDGE_TOLERANCE
                    && Math.abs(existing.getRight() - box.getRight()) <= EDGE_TOLERANCE) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) {
            distinct.add(box);
        }
    }
    return distinct;
}

