cat > /tmp/nh/FullHarness.java <<'EOF'
import com.finboost.bank.statement.parser.config.document.extraction.NativeTableExtractionConfig;
import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.service.document.extraction.IBankSpecificParsingService;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankSpecificParsingServiceImpl;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.bank.*;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.*;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.geometry.*;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.layout.*;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.*;

import java.lang.reflect.Field;
import java.io.File;
import java.util.*;

public class FullHarness {
    static Map<Class<?>, Object> reg = new LinkedHashMap<>();

    static <T> T add(T o) { reg.put(o.getClass(), o); return o; }

    static void wire() throws Exception {
        for (Object o : new ArrayList<>(reg.values())) {
            for (Class<?> c = o.getClass(); c != null && c != Object.class; c = c.getSuperclass()) {
                for (Field f : c.getDeclaredFields()) {
                    if (java.lang.reflect.Modifier.isStatic(f.getModifiers())) continue;
                    Object dep = null;
                    for (Map.Entry<Class<?>, Object> e : reg.entrySet())
                        if (f.getType().isAssignableFrom(e.getKey())) { dep = e.getValue(); break; }
                    if (dep != null && dep != o) { f.setAccessible(true); if (f.get(o) == null) f.set(o, dep); }
                }
            }
        }
    }

    public static void main(String[] a) throws Exception {
        add(new ColumnTypeIdentifier());
        add(new BankTransactionColumnTypeIdentifier());
        add(new BankTransactionTableIdentifier());
        add(new TableColumnNormalizer());
        add(new TableRowNormalizer());
        add(new BankTransactionRowNormalizer());
        add(new BankTransactionTableHeaderIdentifier());
        add(new BankTransactionTableFooterIdentifier());
        add(new StatementBasicDetailExtractor());
        add(new HdfcBankUtil());
        add(new SaraswatBankUtil());
        add(new StandardCharteredBankUtil());
        add(new CatholicSyrianBankUtil());
        add(new MayBankUtil());
        add(new PublicBankUtil());
        BankSpecificParsingServiceImpl bs = add(new BankSpecificParsingServiceImpl());
        AnalyzeDocuments analyze = add(new AnalyzeDocuments());
        wire();

        NativeTableExtractionConfig cfg = new NativeTableExtractionConfig();
        cfg.setEnabled(true); cfg.setMaxPages(Integer.parseInt(a[1])); cfg.setMinTransactionRows(3);
        NativeTransactionTableExtractionService svc = new NativeTransactionTableExtractionService(
            cfg, new NativeLayoutPolicyRegistry(), new NativePdfGeometryExtractor(),
            List.of(new BorderedGridTableLayoutBuilder(), new BoxGuidedTableLayoutBuilder(),
                    new TextAlignedRowSelectedTableLayoutBuilder()));

        File root = new File(a[0]);
        File[] banks = root.listFiles(); Arrays.sort(banks);
        int ok = 0, fail = 0;
        for (File b : banks) {
            if (!b.isDirectory()) continue;
            File[] fs = b.listFiles(); Arrays.sort(fs);
            for (File f : fs) {
                if (!f.getName().endsWith(".pdf")) continue;
                DocumentExtractionRequest req = new DocumentExtractionRequest();
                req.setStatementFile(f); req.setBankName(b.getName());
                long t0 = System.currentTimeMillis();
                NativeExtractionAttempt at = svc.extract(req, cand -> analyzeAndCheck(cand, req, analyze, bs));
                long dt = System.currentTimeMillis() - t0;
                if (at.isSuccessful()) {
                    ok++;
                    System.out.printf("%-32s %-13s %6dms NATIVE layout=%-26s txnRows=%d%n", b.getName(), f.getName(), dt,
                        at.getDiagnostics().getSelectedLayout(), at.getDiagnostics().getNativeRowCount());
                } else {
                    fail++;
                    System.out.printf("%-32s %-13s %6dms ML     %s tried=%s%n", b.getName(), f.getName(), dt,
                        at.getDiagnostics().getSkipOrFailureReason(), at.getDiagnostics().getAttemptedLayouts());
                }
            }
        }
        System.out.println("TOTAL native=" + ok + " mlFallback=" + fail);
    }

    static boolean analyzeAndCheck(DocumentExtractionResult cand, DocumentExtractionRequest req,
                                   AnalyzeDocuments analyze, IBankSpecificParsingService bs) {
        try {
            bs.identifyBankSpecificStatementProcess(cand, req);
            if (cand.isSkipFurtherProcessing()) return has(cand);
            DocumentExtractionResult p = analyze.preProcessForVerificationByHeader(cand, 5);
            if (p != null && p.getPreProcessVerificationResult() != null)
                cand.setPreProcessVerificationResult(p.getPreProcessVerificationResult());
            else {
                DocumentExtractionResult p2 = analyze.preProcessForVerification(cand, cand.getPages().size());
                if (p2 != null && p2.getPreProcessVerificationResult() != null)
                    cand.setPreProcessVerificationResult(p2.getPreProcessVerificationResult());
            }
            analyze.analyzeDocument(cand, true, true, true);
            return has(cand);
        } catch (Exception e) {
            System.out.println("   analysis error: " + e);
            return false;
        }
    }

    static boolean has(DocumentExtractionResult r) {
        for (Page p : r.getPages().values()) {
            if (p.getTables() == null) continue;
            for (Table t : p.getTables().values())
                if (t != null && t.isBankTransactions() && t.getCells() != null && t.getCells().size() > 1) return true;
        }
        return false;
    }
}
EOF
