    public boolean hasBoxes() {
        return boxes != null && !boxes.isEmpty();
    }

    /**
     * Copy of this page geometry with freshly copied words. The rulings and boxes are shared because
     * they are never mutated.
     *
     * <p>Every native layout attempt works on its own word instances so that a rejected attempt (and the
     * bank specific post processors it ran) can never contaminate the next attempt.</p>
     */
    public NativePageGeometry copyWithFreshWords() {
        NativePageGeometry copy = new NativePageGeometry();
        copy.setPageNumber(this.pageNumber);
        copy.setWidth(this.width);
        copy.setHeight(this.height);
        copy.setTextContent(this.textContent);
        copy.setHorizontalRulings(this.horizontalRulings);
        copy.setVerticalRulings(this.verticalRulings);
        copy.setBoxes(this.boxes);
        List<Word> copiedWords = new LinkedList<>();
        if (this.words != null) {
            for (Word word : this.words) {
                copiedWords.add(word.copy());
            }
        }
        copy.setWords(copiedWords);
        return copy;
    }
}

